INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-a2-writing-1$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$A2$tt$, 1, $tt$A2 diagnoostest: kirjutamine (1. variant)$tt$, $tt$A2 tanı testi: yazma (1. varyant)$tt$, $tt$A2 diagnostic: writing (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 141, NULL, $tt$Kirjutamise diagnoostestis on 2 ülesannet.
**Esimeses ülesandes **pead kirjeldama pilti.
**Teises ülesandes **pead kirjutama kirja etteantud teemal.
Sa saad kirjutamistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisteksti ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Kujuta ette, et inimene pildil on sinu sõber. Kirjelda teda oma eesti keele õpetajale. Kuidas on tema nimi? Kui vana ta on? Milline on tema välimus? Missugune on tema iseloom? Mis tööd ta teeb? Mis on tema hobid?","audio":[],"images":[{"src":"testest/mm_320/a2_kirjutamine_1v_ulesanne1.jpg"}],"modelAnswer":"Tema nimi on Anne-Mai ja ta on kakskümmend kuus aastat vana. Ta ei ole pikk ega lühike, paks ega kõhn. Tal on pruunid juuksed ja rohelised silmad. Ta on kena. Anne-Mai ei ole tagasihoidlik ja rahulik. Ta on lõbus, naljakas ja sõbralik.\nTa on ärinaine ja talle meeldib tantsida ja ujuda. Ta käib trennis tihti. Ta armastab ka muusikat.\nTa on väga hea sõper.","modelAudio":[],"modelImages":[],"comment":"Tekst koosneb lihtlausetest. Kõigist ülesandepunktidest on kirjutatud. Teksti koostamisel on kasutatud sõnaraamatu abi, seega esineb tekstis vaid mõni üksik õigekirjaviga ( *sõper ). Sõnavara vastab A2-tasemele. Kirjutaja on kreatiivne. Ehkki pildi põhjal võiks kirjutada naist vallanud emotsioonidest, ei ole see A2-tasemel tasemekohane ega ole seda nõutud ka ülesandes.\nNB! Tekst ei ole kirjutatud reaalses eksamisituatsioonis."},{"title":"2. ülesanne","prompt":"Varsti on jälle jõulud. Kirjuta kiri jõuluvanale. Kirjuta, missugust kingitust sa jõuluvanalt tahad. Kirjelda, millised on sinu jõulud. Küsi jõuluvanalt midagi. Kirja pikkus on umbes 30 sõna.","audio":[],"images":[],"modelAnswer":"Tere jõuluvana!\nSellel aastal olen ma olnud hea laps! Ma tegin palju häid asju. Ma aitasin vana naised üle tanava ja kassi puu otsast alla. Nii, ma sooviksin jõuludelt mõne kingituse. Ma sooviksin autot ja kolm reisi: Peruusse, Hinnasse ja Uus Meremaale.\nMinu jõulud on koss perega ja suure hulga toiduga.\nAga jõuluvana, mul on sulle üks küsimus ka: Mida päkapikud suvel teevad?\nHäid jõule!\nDiana","modelAudio":[],"modelImages":[],"comment":"Diana on ülesande hästi täitnud. Ta on kõigist ülesandepunktidest kirjutanud. Kiri algab sobiva pöördumisega ning lõppeb sobiva hüvastijätuga. Diana kiri on selgelt mõistetav, ehkki on mõned eksimused grammatikas (nt ühildamisreegli eiramine vana naised) ja õigekirjas (nt *tanava, *Hinnasse, *koss). Kiri koosneb valdavalt lihtlausetest. Esineb eksimusi kirjavahemärgistuse osas.\nNB! Diana kiri ei ole kirjutatud reaalses eksamisituatsioonis, kirja koostamisel on kasutatud sõnaraamatut. Kiri on nõutust kaks korda pikem."}]$tt$::jsonb)
