INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-a2-writing-2$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$A2$tt$, 2, $tt$A2 diagnoostest: kirjutamine (2. variant)$tt$, $tt$A2 tanı testi: yazma (2. varyant)$tt$, $tt$A2 diagnostic: writing (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 142, NULL, $tt$Kirjutamise diagnoostestis on 2 ülesannet.
**Esimeses ülesandes **pead kirjeldama pilti.
**Teises ülesandes **pead kirjutama kirja etteantud teemal.
Sa saad kirjutamistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisteksti ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Kujuta ette, et inimene pildil on sinu sõber. Kirjelda teda oma eesti keele õpetajale. Kuidas on tema nimi? Kui vana ta on? Milline on tema välimus? Missugune on tema iseloom? Mis tööd ta teeb? Mis on tema hobid?","audio":[],"images":[{"src":"testest/mm_322/a2_kirjutamine_2v_ulesanne1.jpg"}],"modelAnswer":"Poiss pildil on Marco. Ta on 21 aastat vana ja ta on pärit Itaaliast. Ta on kokk. Marco töötab praegu kallises restoraanis Põhja-Itaalias. Ta on rahulik, rõõmus ja väga loomulik inimene. Ta on ka hea sõber. Marco silmad on hallid ja tema kõrvad on suured. Tal on ilus naeratus. Marcole meeldib kõrvpalli mängida, muusikat kuulata ja oma sõbraga jalutada.","modelAudio":[],"modelImages":[],"comment":"Tekst koosneb lihtlausetest ning sidesõna „ja“ abil seotud lihtlausetest. Kõigist ülesandepunktidest on kirjutatud. Esinevad mõned õigekirjavead ( restoraanis , kõrvpall ) ning grammatikavead ( kallises ). Sõnavara vastab A2-tasemele.\nNB! Tekst ei ole kirjutatud reaalses eksamisituatsioonis."},{"title":"2. ülesanne","prompt":"Varsti lõpeb eesti keele kursus. Kirjuta kiri oma eesti keele õpetajale. Mis sulle kursusel meeldis? Mida uut oled õppinud? Kus ja kuidas sa oma eesti keelt kasutada saad? Kirja pikkus on umbes 30 sõna.","audio":[],"images":[],"modelAnswer":"Tere .................,\nMa olen natuke kurb, eesti keele kursus lõppeb varsti! Mulle meeldis, praegu, ma räägin Eesti keelt. Enne ma tulisin Eestisse, ma ei rääkisin Eesti keelt! Mulle meeldis kirjutada kirjad iga nädal!\nKõik, ma olen õppinud, on uus meile. Aga eestlasel on erinevaid väljendeid Iirlased ja inglise keelest.\nTihti ma räägin eesti keelt poodis kui ma saan. Ka ma räägin eesti keelt minu Eestlased sõbradaga. Ma lootan kirjutada kirja eesti keeles Rachelile, Lindale ja Cindyle kui ma tulen Iirimaale tagasi. Mul on minu Facebook profiil ja mu arvuti eesti keeles nii ma vaatan eesti keelt iga päev.\nMairin","modelAudio":[],"modelImages":[],"comment":"Mairin on ülesande suurepäraselt täitnud. Ta on kõigist ülesandepunktidest kirjutanud. Kiri algab sobiva pöördumisega. Laused on seotud lihtsate sidesõnadega ja , aga , kui . Kirjas kasutatud sõnavara vastab A2-tasemele. Mairini kirjas on mitmeid eksimusi nii grammatikareeglite ( *tulisin , *ei rääkisin , *poodis ) kui ka ortograafiareeglite vastu ( *Eesti keel , *Iirlased ). Siiski on Mairini kiri mõistetav.\nNB! Mairini kiri on nõutust kolm korda pikem ega ole kirjutatud reaalses eksamisituatsioonis."}]$tt$::jsonb)
