INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-a2-speaking-1$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$A2$tt$, 1, $tt$A2 diagnoostest: rääkimine (1. variant)$tt$, $tt$A2 tanı testi: konuşma (1. varyant)$tt$, $tt$A2 diagnostic: speaking (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 151, NULL, $tt$Rääkimise diagnoostestis on 2 ülesannet.
**Esimeses ülesandes **pead rääkima etteantud teemal. Selleks kasutad sa skeemi.
**Teises ülesandes ** pead rääkima infokaardi (kalender) põhjal.
Sa saad rääkimistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidist (helifaili) ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Räägi teemal „Vaba aeg”. Võid kasutada teemaga seotud sõnu skeemilt.","audio":[],"images":[{"src":"testest/mm_324/a2_raakimine_1v_ulesanne1.jpg"}],"modelAnswer":null,"modelAudio":["testest/mm_325/a2_raakimine1_v1_mees.mp3"],"modelImages":[],"comment":"Mikhail saab ülesande täitmisega suurepäraselt hakkama. Ta räägib ladusalt enda vaba aja veetmise eelistustest, kasutades peaaegu kõiki mõtteskeemi sõnu. Mikhail tunneb mitmeid grammatikareegleid ning oskab neid kasutada (nt infinitiivi valik: meeldib + da -infinitiiv, oskan + da -infinitiiv).\nMikhaili kõnes esinevad siiski mõned eksimused grammatika osas, nt ühildamisvead ( *mulle meeldib erinevad raamatud , *õpin eesti keelt vaba ajal ), rektsioonivead ( *vaatan filmid ), ajavormide kasutus ( *ma olen teinud jalgpalli ), eitus ( *praegu ma ei teha sporti ). Kõnes on mõned pausid, esineb sõnadeotsimist ja ümbersõnastamist „ õhtul min.. oma naisega süüa.. “. Mikhailil on aktsent, kuid tema hääldus ei sega teksti mõistmist."},{"title":"2. ülesanne","prompt":"Näed Maria kalendrit. Kalendris on neljapäeva, 17. aprilli päevakava. Vaata kalendrit ja räägi, mida Maria neljapäeval teeb. Neljapäev, 17. aprill 8.00 15.00 9.00 helista perearstile!\nreserveeri laud restoranis! 16.00 10.00 aeroobika 17.00 11.00 18.00 kontsert kirikus 12.00 19.00 kontsert kirikus 13.00 lõuna Robertiga 20.00 õhtusöök restoranis \"Capri\" 14.00 juuksur 21.00","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_326/a2_raakimine2_v2_naine.mp3"],"modelImages":[],"comment":"Kõneleja saab ülesande täitmisega suurepäraselt ja täpselt hakkama. Ta räägib Maria päevakavast väga ladusalt ja selgelt. Kõneleja räägib ainult sellest, mis kalendris täpselt kirjas on. Tekst on grammatiliselt peaaegu veatu, esineb vaid mõni üksik eksimus, nt *kell 10 ta läheb aeroobikas . Kõneleja suudab ebasobiva lausealustuse sujuvalt ja kiirelt ümber sõnastada, nt Juba kell kaks on.. ta läheb juuksurisse ."}]$tt$::jsonb)
