INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-a2-speaking-2$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$A2$tt$, 2, $tt$A2 diagnoostest: rääkimine (2. variant)$tt$, $tt$A2 tanı testi: konuşma (2. varyant)$tt$, $tt$A2 diagnostic: speaking (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 152, NULL, $tt$Rääkimise diagnoostestis on 2 ülesannet.
**Esimeses ülesandes **pead rääkima etteantud teemal. Selleks kasutad skeemi.
