--changeset testest:task-testest-diagnostic-a2-speaking-3 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-a2-speaking-3$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$A2$tt$, 3, $tt$A2 diagnoostest: rääkimine (3. variant)$tt$, $tt$A2 tanı testi: konuşma (3. varyant)$tt$, $tt$A2 diagnostic: speaking (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 153, NULL, $tt$Rääkimise diagnoostestis on 2 ülesannet.
**Esimene ülesanne** on küsimuste esitamine. Saad teema ja piltidega ideekaardi. Sa pead esitama vähemalt 5-6 teema ja ideekaardiga seotud küsimust.
**Teine ülesanne **on pildi kirjeldamine. Sa pead kirjeldama kõike, mida sa pildil näed (asju, inimesi, sündmusi, tegevusi jne).
Rääkimistest on väga hästi tehtud, kui saad ülesannetest aru, sinu kõne on arusaadav, oskad moodustada arusaadavaid lauseid ja oskad küsida asjakohaseid küsimusi.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Vaata fotosid ja esita etteantud teemal küsimusi. **Loomad**\nMilliseid loomi sa oled näinud? Loomaaed Mets Koduaed","audio":[],"images":[{"src":"testest/mm_332/a2_raakimine_3v_yl1_1.jpg"},{"src":"testest/mm_333/a2_raakimine_3v_yl1_2.jpg"},{"src":"testest/mm_334/a2_raakimine_3v_yl1_3.jpg"},{"src":"testest/mm_335/a2_raakimine_3v_yl1_4.jpg"},{"src":"testest/mm_336/a2_raakimine_3v_yl1_5.jpg"},{"src":"testest/mm_337/a2_raakimine_3v_yl1_6.jpg"},{"src":"testest/mm_338/a2_raakimine_3v_yl1_7.jpg"},{"src":"testest/mm_339/a2_raakimine_3v_yl1_8.jpg"},{"src":"testest/mm_340/a2_raakimine_3v_yl1_9.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"Ülesanne on hästi täidetud siis, kui teemast saadakse aru ja osatakse küsida lühikesi asjakohaseid küsimusi, väljumata etteantud teema piiridest."},{"title":"2. ülesanne","prompt":"Vaata fotot ja räägi, mida sa seal näed.","audio":[],"images":[{"src":"testest/mm_341/a2_raakimine_3v_yl2.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"Ülesanne on hästi täidetud siis, kui suudetakse lühidalt kirjeldada etteantud fotot, tuua fotolt välja olulisemad detailid, kasutada teemakohaseid sõnu ning moodustada arusaadavaid lauseid."}]$tt$::jsonb)
