--changeset testest:task-testest-sample-a2-writing runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-a2-writing$tt$, $tt$sample$tt$, $tt$writing$tt$, $tt$A2$tt$, NULL, $tt$A2 tasemeeksami näidistest: kirjutamine$tt$, $tt$A2 sınav örneği: yazma$tt$, $tt$A2 sample exam: writing$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 140, 30, $tt$Kirjutamise näidistestis on kaks ülesannet.
**Esimeses ülesandes** tuleb sul koostada tekst. Saad andmed (visiitkaardil) ja küsimused, mis aitavad sind teksti koostamisel.
**Teises ülesandes** tuleb sul koostada tekst mingil kindlal teemal. Ülesande juhises on kirjas, millest pead kirjutama.
Kirjutamistesti tegemiseks on aega **30 minutit**.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Näed visiitkaarti ühe inimese andmetega. Palun kirjuta: Kes ta on? Kus ta töötab? Millal ta töötab? Kuidas saad temaga kontakti? Teksti nõutav pikkus on umbes 25 sõna.","audio":[],"images":[{"src":"testest/mm_367/a2_kirjutamine_1ulesanne.png"}],"modelAnswer":"See on noor naine Annika Oja, ta on juuksur. Ta töötab ilusalongi [õige: ilusalongis ] „Laine“. Tema tööaeg on esmaspäev [ õige: esmaspäeval ] ja teisipäev [ õige: teisipäeval ] kellast [ õige: kella ] 12.00 kuni 18.00. Reedest laupäevani kellast [ õige: kella ] 10.00 kuni 15.00. Temaga kontakti saab telefoni kaudu 54667824 või sõida kohale Elva, Männi tn 4 [ õige: temaga saab kontakti telefoninumbril 54667824 või saab sõita kohale Elvasse, Männi tn 4 ].","modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Sinu eesti keele õpetaja palus sul kirjeldada oma lemmiklooma. Kirjuta teemal \"Minu lemmikloom\". Missugune? Mida sööb? Mida oskab? Teksti nõutav pikkus on vähemalt 30 sõna.","audio":[],"images":[],"modelAnswer":"Meil on suur koer. Ta on meie lemmikloom, sest meil ei ole teist loomi [ õige: looma ]. Ta sööb kõik [ õige: kõike ], mis [ õige: mida ] mina annan. Ma keedan talle iga päev sooja toidu [ õige: toitu ]. Aga rohkem talle ikka meeldib [ õige: meeldivad ] värsked kontid [ õige: kondid ]. Ta oskab istuda, kui ma käskin [ õige: käsin ], või anda käppa.","modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
