--changeset testest:task-testest-sample-a2-speaking runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-a2-speaking$tt$, $tt$sample$tt$, $tt$speaking$tt$, $tt$A2$tt$, NULL, $tt$A2 tasemeeksami näidistest: rääkimine$tt$, $tt$A2 sınav örneği: konuşma$tt$, $tt$A2 sample exam: speaking$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 150, 15, $tt$Rääkimise näidistestis on 2 ülesannet. Test kestab umbes 15 minutit.
Esimeses ülesandes on kaks osa.
**Esimeses osas** pead rääkima mingi teemaga seotud pildi kohta. Sinu ülesanne on rääkida, mida sa pildil näed: inimesi, tegevust, asju.
**Teises osas** jääb rääkimise teema samaks. Sa pead vastama teemalehe 4-5 küsimusele.
Teises ülesandes saad ideekaardi. Ideekaardil on teema, sellega seotud märksõnad ja pildid. Sinu ülesanne on ideekaardi abil küsida teiselt inimeselt küsimusi ja vastata tema küsimustele.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Ülesanne koosneb kahest osast: Kirjelda kõike, mida pildil näed: inimesi, tegevust, asju. Vasta eksamineerija küsimustele.\n**I osa**\n**teema: Vaba aeg**\n**II osa**\n**teemaleht **\n**(eksamineerijale)**\n**Vaba aeg** Mitu päeva nädalas sa töötad? Millised nädalapäevad on sul puhkepäevad?\nKas sul on nädalavahetusel palju või vähe vaba aega?\nKas sa saad puhkepäeva hommikul kaua magada? Mis kell sa puhkepäeva hommikul ärkad?\nMida sa nädalavahetusel tavaliselt kodus teed?\nKas sa käid vabal ajal kinos? Kui tihti sa kinos käid? Millised filmid sulle meeldivad? Kellega sa kinno lähed?\nKas sulle meeldib vabal ajal sporti teha? Mis sporti sa teed? Kus sa tavaliselt sporti teed?\nKui tihti sa käid looduses jalutamas? Kus? Kellega?","audio":[],"images":[{"src":"testest/mm_370/naidis_a2_raakimine.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Kasuta pilte ja räägi, mida sa ostad erinevatest kauplustest.\n**Ostud**\n**Mida sa ostad?**\nToidukauplus\nTehnikakauplus\nRaamatukauplus","audio":[],"images":[{"src":"testest/mm_371/naidis_a2_raakimine_2yl_1.png"},{"src":"testest/mm_372/naidis_a2_raakimine_2yl_2.png"},{"src":"testest/mm_373/naidis_a2_raakimine_2yl_3.png"},{"src":"testest/mm_374/naidis_a2_raakimine_2yl_4.png"},{"src":"testest/mm_375/naidis_a2_raakimine_2yl_5.png"},{"src":"testest/mm_376/naidis_a2_raakimine_2yl_6.png"},{"src":"testest/mm_377/naidis_a2_raakimine_2yl_7.png"},{"src":"testest/mm_378/naidis_a2_raakimine_2yl_8.png"},{"src":"testest/mm_379/naidis_a2_raakimine_2yl_9.png"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
