--changeset testest:task-testest-diagnostic-b1-writing-1 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b1-writing-1$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$B1$tt$, 1, $tt$B1 diagnoostest: kirjutamine (1. variant)$tt$, $tt$B1 tanı testi: yazma (1. varyant)$tt$, $tt$B1 diagnostic: writing (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 241, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **pead täitma kümnest küsimusest koosneva küsimustiku.
**Teises ülesandes **on toodud kiri, millele sul tuleb vastus koostada, lähtudes tööjuhendist.
Sa saad ise kirjutamistesti ülesandeid täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisvastust ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Uuringufirma palub sul täita küsimustik telesaadete vaatamise kohta. Vaata küsimustikku ja vasta igale küsimusele.","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"naine 24 aastat vana abiellus Sillamäe, Ida-Virumaa kaks-kolm korda nädalas umbes 8 tundi Esimene Balti kanaal, seal on kõige huvitavam saated. Huumor saateid ja uudised. On vaja teada mis maailmas toimub. Meeldivad lõbusaid saateid. Pole kõikidega, mõnikord igav. Väheneda seriaalide arv, vähem reklaameid. Kirjutaja sai ülesandest aru, vastas kõigile küsimustele ning põhjendas, kus vaja. Ta kasutas nii sõnavara kui ka grammatikat hästi: töös esinevad vaid mõned grammatika- ja õigekirjavead (nt abiellus , kanaal , huvitavam saated, huumor saateid, vähem reklaameid ) ning sõnakasutusvead (nt väheneda seriaalide arv ), aga see ei sega arusaamist. Kirjutamisülesanne on hästi sooritatud."},{"title":"2. ülesanne","prompt":"Said oma puhkusel olevalt kolleegilt kirja. Loe kolleegi kiri läbi ja kirjuta talle vastuskiri. Vasta kolleegi kirjas olevatele küsimustele ning esita ka talle 2-3 küsimust reisi ja tema tagasituleku kohta. Kirja pikkus on umbes 100 sõna.\nTere…\nMa pole sind ammu näinud. Kuidas sul läheb ja millega sa tegeled?\nMina olen juba terve nädala puhanud Kanaari saartel. Olen siin koos perega ja me elame mugavas hotellis üsna mere ääres. Ilm on siin on väga soe (ligi 30 kraadi) ja me käime iga päev meres ujumas. Vesi on nagu basseinis!\nOleme käinud ka huvitavatel ekskursioonidel looduses ja kohanud erinevaid inimesi. Olen väga rahul, et saan niimoodi puhata ega pea tööasjadele mõtlema.\nMis meil töö juures uudist on? Kas ülemus on minu järele ka küsinud?\nMissugune on praegu ilm Eestis? Mida huvitavat on sinu elus juhtunud?\nOotan sinu vastust.\nTervitades\nRein","audio":[],"images":[],"modelAnswer":"Tere, kallis Rein!\nRõõm sind jälle kuulda. Mul kõik läheb hästi: iga päev käin tööl, pärast lähen koos sõbradega lauatennist mängida ja kui mul juhtub puhkepäev, veedan seda koos perega.\nIlm Eestis on päris hea: päike paistab ja vihm sajab päris harva. Seetõttu on mõnikord igav töötada: akna taga on soe ja ilus ilm, aga tööl ei juhtu midagi uut. Ainult meie sekretär Svetlana küsis sinu järele, sest ilma sinuta on tal väga raske töötada, sind siin armastatakse.\nElus mul midagi uut ka ei juhtunud ja mulle see meeldib. Nagu tead, ma ei armasta muutust.\nKas sulle meeldib niimoodi puhata välismaal? Võib-olla Eestis on parem? Millal te saabute koju ja millal sa tööle tuled?\nOotan sinu vastust.\nTervitades\nAleksei","modelAudio":[],"modelImages":[],"comment":"Kirjutaja sai ülesandest aru ja täitis selle õigesti. Kiri on kirjutataud vastavalt teemale ja kirja sisu on väga hea. Kirjutaja andis vajaliku info edasi ning vastas kõikidele küsimustele. Kiri on loogiline ja õige pikkusega. Sõnavara- ja grammatikakasutuses esineb mõningaid vigu (sain sind aru, lähen koos sõbradega lauatennist mängida , vihm sajab, kui mul juhtub puhkepäev), aga see ei sega kirjast arusaamist. Kirjutamisülesanne on hästi sooritatud."}]$tt$::jsonb)
