--changeset testest:task-testest-diagnostic-b1-writing-2 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b1-writing-2$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$B1$tt$, 2, $tt$B1 diagnoostest: kirjutamine (2. variant)$tt$, $tt$B1 tanı testi: yazma (2. varyant)$tt$, $tt$B1 diagnostic: writing (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 242, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **pead kirjutama kirja, lähtudes tööjuhendist.
**Teises ülesandes **pead kirjutama teksti etteantud teemal.
Sa saad ise kirjutamistesti ülesandeid täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisvastust ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Ostsid kinopiletid ja soovid oma sõbra kinno kutsuda. Kirjuta talle teade, kasutades etteantud küsimusi. Mis ettepanek sul on? Mis filmi lähete vaatama? Millal ja mis kinos on film? Millal ja kus te kokku saate? Teate pikkus on umbes 50 sõna.","audio":[],"images":[],"modelAnswer":"Tere Vika!\nMinul on sulle üks ettepanek. Tahan kutsuda sind kinno, sest juba ostnud kinopiletid \"2012\" filmile. Meie filmiseans toimub 7. detsembril kinoteatril \"Coca Cola Plaza\" kell 19. Sa oled rääkinud, et oled vaba sel päeval, siis saame kokku Hobujaamas kell pool seitse. Ootan sind, ära hiline palun.\nOlesja","modelAudio":[],"modelImages":[],"comment":"Kirjutaja sai ülesandest aru ning vastas kõigile küsmustele. Ta kasutas nii sõnavara kui ka grammatikat hästi: töös esinevad vaid mõned grammatika- ja õigekirjavead (nt sest juba ostnud kinopiletid , filmiseans , kinoteatril ), aga see ei sega arusaamist. Kirjutamisülesanne on väga hästi sooritatud."},{"title":"2. ülesanne","prompt":"Õpetaja palub sul kirjutada jutu päevast, mille veetsid koos perega. Kirjuta, millal see oli, mida te koos tegite, kus käisite, mida nägite ja mis eriti meeldis. Teksti pikkus on umbes 100 sõna.","audio":[],"images":[],"modelAnswer":"Eelmisel nädalavahetusel istusin kodus, aga mul ei olnud igav. Kogu meie perekond istus laua taga ja sõi torti. Me jutustasime, mis toimus nädala jooksul. Pärast me otsustime loomaaia minna, kus nägime igasugusi eksootilisi loome ja linnu. See kõik mulle eriti meeldis, sest mina armastan aega veeta loomadele vaadates. Ka olime sel päeval huvitavas baaris, kus vaatasime jalgpallimatši, Eestimaa võitis ja minu tuju sai eriti heaks. Sellega minu parem päev lõppenud, aga ma loodan, et mina ja pere kordame seda ja kõik läheb veel huvitavam ja lõbusam.","modelAudio":[],"modelImages":[],"comment":"Kirjutaja sai ülesandest aru ja täitis selle õigesti. Jutt on kirjutataud vastavalt teemale ja selle sisu on hea. Kirjutaja andis vajaliku info edasi ning kasutas kõiki etteantud punkte. Kirjutis on nõutust veidi lühem (87 sõna). Esineb mõningaid grammatika- ja sõnakasutusvigu ( otsustime loomaaia minna, igasugusi , loomadele vaadates, tuju sai heaks, sellega päev lõppenud , kõik läheb huvitavam ja lõbusam ), aga see ei sega arusaamist. Kirjutamisülesanne on hästi sooritatud."}]$tt$::jsonb)
ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, skill = EXCLUDED.skill, cefr_level = EXCLUDED.cefr_level, variant = EXCLUDED.variant, title = EXCLUDED.title, title_tr = EXCLUDED.title_tr, title_en = EXCLUDED.title_en, source = EXCLUDED.source, sort_order = EXCLUDED.sort_order, time_limit_minutes = EXCLUDED.time_limit_minutes, intro = EXCLUDED.intro, tasks = EXCLUDED.tasks;

