INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b1-speaking-1$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B1$tt$, 1, $tt$B1 diagnoostest: rääkimine (1. variant)$tt$, $tt$B1 tanı testi: konuşma (1. varyant)$tt$, $tt$B1 diagnostic: speaking (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 251, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul kõneleda etteantud teemal, vastates küsimustele.
**Teises ülesandes **on vaja rääkida etteantud teemal, sealjuures on abiks küsimused ja pildid.
Sa saad rääkimistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidisvastust (helifail) ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Vestluse teema on \"Perekond ja kodu\". Kuula küsimusi ja vasta.","audio":["testest/mm_432/b1_raakimine_1_variant_1_ylesanne.mp3"],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"Rääkija sai ülesandest aru ja vastas kõigile küsimustele. Küsimustele antud vastused olid selged ja arusaadavad. Kõneleja kasutas sõnavara ja grammatikat üsna õigesti: esines vaid üksikuid sõnakasutus- ja grammatikavigu, mis ei sega arusaamist. Ülesanne on väga hästi sooritatud."},{"title":"2. ülesanne","prompt":"Räägi teemal \"Reisimine\". Rääkimisel on sulle abiks küsimused ja pildid. Kas sulle meeldib reisida? Miks? Kus sa oled reisinud? Kus sa viimati käisid? Kui kaua see reis kestis? Kuidas sulle meeldib reisida (mis transpordiga, kellega koos jne). Miks? Kuhu sa soovid tulevikus reisida? Miks? Missugused peaksid olema reisitingimused (ööbimine, aastaaeg, puhkus/sport jne)?","audio":[],"images":[{"src":"testest/mm_688/b1_raakimine_2.jpg"},{"src":"testest/mm_691/b1_raakimine_5.jpg"},{"src":"testest/mm_689/b1_raakimine_3.jpg"},{"src":"testest/mm_690/b1_raakimine_4.jpg"},{"src":"testest/mm_687/b1_raakimine_1.jpg"}],"modelAnswer":null,"modelAudio":["testest/mm_438/b1_raakimine_1_variant_2_ylesanne.mp3"],"modelImages":[],"comment":"Rääkija sai ülesandest aru ja täitis selle õigesti. Ta oskas kasutada etteantud infot ja seda edasi anda. Küsimustele andis ta täpsed vastused. Ta suutis rääkida ettevalmistuseta, kõne oli hästi mõistetav, hääldus selge ja arusaadav. Esines üksikuid sõnakasutus- ja grammatikavigu, mis ei sega arusaamist. Ülesanne on väga hästi sooritatud."}]$tt$::jsonb)
