--changeset testest:task-testest-diagnostic-b1-speaking-2 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b1-speaking-2$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B1$tt$, 2, $tt$B1 diagnoostest: rääkimine (2. variant)$tt$, $tt$B1 tanı testi: konuşma (2. varyant)$tt$, $tt$B1 diagnostic: speaking (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 252, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul kõneleda etteantud teemal, vastates küsimustele.
**Teises ülesandes **on vaja rääkida etteantud teemal, sealjuures on abiks küsimused ja pildid.
Sa saad ise rääkimistesti ülesandeid täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidist (helifaili) ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Vestluse teema on \"Töökoht ja amet\". Kuula küsimusi ja vasta. Kuula näidisvastust ja seejärel loe kommentaari.","audio":["testest/mm_440/b1_raakimine_2_variant_1_ylesanne.mp3"],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"Rääkija sai ülesandest aru ja vastas kõigile küsimustele. Küsimustele antud vastused olid selged ja arusaadavad. Kõneleja kasutas sõnavara ja grammatikat õigesti: esines vaid paar grammatikaviga (palju toredad inimesed ), mis ei sega arusaamist. Ülesanne on väga hästi sooritatud."},{"title":"2. ülesanne","prompt":"Räägi teemal \"Tervislik toitumine\". Rääkimisel on sulle abiks küsimused ja pildid. Kui tihti sa sööd? Kus sa sööd? Kas sa teed ise süüa? Milliseid toite sulle meeldib teha? Mida sulle meeldib süüa? Missugune on tervislik toit? Kas on vaja süüa tervislikult? Miks? Kas sina sööd tervislikult?","audio":[],"images":[{"src":"testest/mm_685/b1_2_variant_raakimine_4.jpg"},{"src":"testest/mm_686/b1_2_variant_raakimine_5.jpg"},{"src":"testest/mm_683/b1_2_variant_raakimine_2.jpg"},{"src":"testest/mm_684/b1_2_variant_raakimine_3.jpg"},{"src":"testest/mm_682/b1_2_variant_raakimine_1.jpg"}],"modelAnswer":null,"modelAudio":["testest/mm_446/b1_raakimine_2_variant_2_ylesanne.mp3"],"modelImages":[],"comment":"Rääkija sai ülesandest aru ja täitis selle õigesti. Ta oskas kasutada etteantud infot ja seda edasi anda. Küsimustele andis ta täpsed vastused. Ta suutis rääkida ettevalmistuseta, kõne oli hästi mõistetav, hääldus selge ja arusaadav. Esines üksikuid sõnakasutus- ja grammatikavigu, mis ei sega arusaamist. Ülesanne on väga hästi sooritatud."}]$tt$::jsonb)
