--changeset testest:task-testest-diagnostic-b1-speaking-3 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b1-speaking-3$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B1$tt$, 3, $tt$B1 diagnoostest: rääkimine (3. variant)$tt$, $tt$B1 tanı testi: konuşma (3. varyant)$tt$, $tt$B1 diagnostic: speaking (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 253, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimene ülesanne **on pildi kirjeldamine ja vestlus etteantud teemal. Vestluse käigus pead väljendama oma arvamust ja soove, kirjeldama erinevaid võimalusi ning lühidalt põhjendama oma eelistusi.
**Teine ülesanne **on rollimäng, kus osalevad kaks inimest: ühel tuleb infot küsida ja teisel infot anda. Ülesanne on täidetud, kui vastused on leitud vähemalt viiele küsimusele.
Rääkimistest on väga hästi täidetud, kui saad ülesannetest aru, sinu kõne on mõistetav, oskad ennast igapäevateemadel üsna ladusalt väljendada, oskad kasutada etteantud infot, oskad küsimusi moodustada, oskad küsimustele vastused leida ja jõuad vestluskaaslasega kokkuleppele.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Ülesanne koosneb kahest osast: Kirjelda, mida või keda sa fotodel näed, mida fotol tehakse, kus tegevus toimub jms. Fotod, mida kirjeldasid, on lemmikloomadest kodus ja õues. Aruta teise testitavaga, mida teie arvate lemmiklooma pidamisest korteris. Milline loom selleks sobib ja mis tingimused tema pidamiseks peavad olema?\n**Lemmikloomad** Pilt 1 Pilt 2","audio":[],"images":[{"src":"testest/mm_448/b1_raakimine_3v_yl1_1.jpg"},{"src":"testest/mm_449/b1_raakimine_3v_yl1_2.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Antud ülesanne on rollimäng, kus ühel testitaval tuleb infot küsida ja teisel infot anda.\nÜhele testitavale antakse küsimusekaart, kus on märksõnad, mille põhjal küsimusi esitada. Teisele testitavale antakse vastusekaart, mille põhjal küsimustele vastata. Küsimusekaardi saanud testitav peab ette kujutama, et ta helistab kaardil märgitud asutusse. Vastusekaardi saanud testitav peab ette kujutama, et ta on kaardil märgitud asutuse töötaja.\nÜlesanne on täidetud, kui vastused on leitud vähemalt viiele küsimusele. **Küsimustekaart** **Vastusekaart** **Mööbli**\n** komisjonikauplus**\nAadress?\nMillal avatud?\nKaubavalik?\nTransport?\nSoodustused?\nTäpsem info?\n**Mööbli komisjonikauplus**\nTallinn, Soo 18\n(bussid 51, 53, bussipeatus Soo)\nE−R 10.00−18.00\nL 10.00−16.00\nP suletud\nMüügil suur valik uut, vähe kasutatud ja odavat mööblit.\nIga päev uus kaup.\nVõtame komisjonimüüki mööblit ja kodumasinaid.\nSaame pakkuda ka transporti. Hind kokkuleppel.\n**Kuu lõpuni mööbli vedu tasuta!**\nKülastage meie kodulehte:\nwww.komisjonimoobel.ee","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
