--changeset testest:task-testest-diagnostic-b2-writing-1 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b2-writing-1$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$B2$tt$, 1, $tt$B2 diagnoostest: kirjutamine (1. variant)$tt$, $tt$B2 tanı testi: yazma (1. varyant)$tt$, $tt$B2 diagnostic: writing (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 341, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **pead kirjutama kokkuvõtte, milles analüüsid ja kommenteerid toodud andmeid ning esitad nende kohta oma isikliku seisukoha.
**Teine ülesanne **on etteantud arvamusele oma põhjendatud kommentaari kirjutamine.
Sa saad kirjutamistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisteksti ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Tutvu analüüsiga „Neljaliikmelise pere ühe kuu kulud”. Analüüsi, millele kulutab pere oma raha. Esita oma arvamus kulutuste kohta. Võrdle pere kulutusi oma kulutustega. Teksti pikkus olgu umbes 120 sõna. **Neljaliikmelise pere ühe kuu kulud** Töötavad vanemad, kelle peres kasvavad kuueaastane poeg ja 1,5-aastane tütar.\nElavad 3-toalises korteris Mustamäel.\nPere kasutab transpordiks oma autot ja pereemal on kuukaart.\nLapsi hoiab päeval vanaema. Eluasemekulud 130 € Elekter 35 € Toit 320 € Riidekaubad, jalanõud 65 € Majapidamiskulud 65 € Ravimid 35 € Transport, bensiinikulu 130 € Meelelahutus: kontsert, teater 35 € Raamatud, perioodika 35 € Muud kulud 130 € Kokku 980 €","audio":[],"images":[],"modelAnswer":"Tutvusin analüüsiga „Neljaliikmelise pere ühe kuu kulud”. Peres töötavad vanemad, nendel on kuueaastane poeg ja 1,5-aastane tütar. Elavad nad 3-toalises korteris Mustamäel. Lapsed ei käi lasteaias. Perel on tavalised kulud: eluasemekulud (130 eurot), elekter (35 eurot), toit (320 eurot), riidekaubad (65 eurot), majapidamiskulud (65 eurot) ja muud kulud. Kokku on kuus kulusid 980 eurot. Arvestades, et pere koosneb neljast liikmest, summad on üsna väikesed. Ma arvan, et see pere ei saa lubada endale midagi erilist, näiteks sõita välismaale. Kokkuvõteks ma võin öelda, et pere elab üsna ökonoomselt ja kulutab oma raha ainult hädavajalikkudele asjadele.\nKui võrrelda kulutused minu perega, siis on nähtavad suured erinevused. Kuna ma elan kahekesi minu isaga, toitudele ja riidekaubadele me kulutame kaks korda vähem kui neljaliikmeline pere. Erinevus on ka selles, et ma koos isaga kasutame ühistransporti. Ostame kolme kuu sõidukaardi ja see tuleb ökonoomne välja. See on ainuke pluss ühistranspordist. Mis puutub eluasemekuludesse, siin ei ole praktiliselt erinevusi. Meie korter on kahetoaline, aga iga kuu me maksame umbes 130 eurot. Aga me püüame kasutada vett ja valgust vähem, kui meil on olemas selline võimalus.","modelAudio":[],"modelImages":[],"comment":"Oskab kirjutada kavakindlat argumenteeritud arvamuskirjutist, oskab tuua välja olulisemad seisukohad, hinnata-võrrelda erinevaid arvamusi, esitada põhjendatud poolt- või vastuväiteid. Oskab teksti siduda, kasutada erinevaid asesõnu, määrsõnu, sidendeid, kirjavahemärke."},{"title":"2. ülesanne","prompt":"Tutvu arvamusega. Kommenteeri seda. Teksti pikkus olgu umbes 160 sõna. Iga Eesti kodanik peaks avama ravikindlustuskonto, millelt kaetaks ravi, ravimite ja muud kulud juhtudel, kui ravi kestab alla aasta. Ravikindlustuskontole teeksid sissemakseid nii kindlustatu ise, tööandja kui ka riik (laste jt eest). Kontoga kaasnev kindlustus peaks sisaldama kõiki terviseriske. Pikaajaline ravi finantseeritaks riigieelarvest.","audio":[],"images":[],"modelAnswer":"Ma tutvusin arvamusega, et kõik Eesti kodanikud peavad avama ravikindlustuskonto. Ma olen sellega nõus ja mitte ka. Ühest küljest, kui riigi majandus on heal tasemel ja inimeste tulud annavad võimalusi avada seda ravikindlustuskonto, suus miks mitte. Lisaks sellele on ikka hea see, et neid ei ravita teiste inimeste maksude abil, aga 50% tema oma arve kaudu. Ma olen nõus, et tööandja ka teeb makseid, sest ta peab hoolitsema oma töötaja tervise eest. Ja kui terviseprobleem tekib tööl, suus on õige, et maksab tööandja.\nTeisest küljest, tänapäeva maailmas mitte kellelgi ei ole lisaraha selle konto avamiseks. Iga kuu peab planeerima oma raha, mis on vaja tasuda ja mis on vaja osta. Ja võib-olla ei tule kunagi sellest kontost kasu, milleks siis seda kontot avada. Ja kui inimene sureb, siis kuhu need rahad lähevad?\nKokkuvõtteks saan ma öelda, et kui oleks küsitlus, kas teha ravikindlustuskonto kohustuslikuks või mitte, siis mina vastaksin, et see idee on väga mugav. See kaitseb inimest, kui tal on vaja, tal on raha ravimitele ja ta saab arstiabi.","modelAudio":[],"modelImages":[],"comment":"Oskab kommenteerida teksti, arutleda erinevate seisukohtade ja peamiste teemade üle, avaldada oma argumenteeritud arvamust, oskab oma väljendust varieerida. Oskab teksti siduda, kasutada erinevaid asesõnu, määrsõnu, sidendeid, kirjavahemärke."}]$tt$::jsonb)
