--changeset testest:task-testest-diagnostic-b2-writing-2 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b2-writing-2$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$B2$tt$, 2, $tt$B2 diagnoostest: kirjutamine (2. variant)$tt$, $tt$B2 tanı testi: yazma (2. varyant)$tt$, $tt$B2 diagnostic: writing (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 342, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **pead kirjutama kokkuvõtte, milles analüüsid ja kommenteerid esitatud andmeid ning annad nende kohta oma seisukoha.
**Teine ülesanne **on etteantud arvamusele oma põhjendatud kommentaari kirjutamine.
Sa saad ise kirjutamistesti ülesandeid täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisvastust ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Tutvu küsitluse „Politsei lühinumbrile 110 helistamise tulemuse ja rahulolu” tulemustega. Analüüsi rahulolu politsei lühinumbrile helistamisega. Avalda arvamust tulemuste kohta. Esita põhjusi, miks helistatakse politsei numbrile. Teksti pikkus olgu umbes 120 sõna.","audio":[],"images":[{"src":"testest/mm_456/b2_kirjutamine_2v_ulesanne1.jpg"}],"modelAnswer":"Pärast skeemi analüüsimist, tuli välja, et selliste inimeste protsent, kes helistasid politsei lühinumbrile 110 ning ei saanud sealt üldse mingit abi, on 79%. Just niisugune protsent inimesi ei ole rahul politsei tööga. 7% on aga enam-vähem rahul. Sellega, et abi saabus liiga hilja on täiesti rahul 3% ja enam-vähema rahul 41%. 51%le ei meeldi, et abi saabub mitte õigeks ajaks vaid palju hiljem. Neid, kellele anti nõu ja kes oli täiesti rahul on 57%. Kui politsei kiiresti jõuab kohale, annab nõua ja kuidagi aitab, siis enamik inimestest on sellega enam-vähem või täiesti rahul. Kui aga inimesed ei saanud mingit abi ja politseid saabus liiga hilja, siis enamik neist ei ole täiesti rahul.\nNeed tulemused näitavad seda, et paljud meist tahavad abi saada just politseist. Üks põhjus, et inimesed helistavad politsei numbrile, on see, et nende lühinumber on esimene asi, mis meil meelde tuleb, kui meil on probleemid. Veel võivad põhjused olla, kui nad olid pealtnägijad, kui nende elu on ohus, kui midagi varastati.","modelAudio":[],"modelImages":[],"comment":"Oskab kirjutada kavakindlat argumenteeritud arvamuskirjutist, oskab tuua välja olulisemad seisukohad, hinnata-võrrelda erinevaid arvamusi, esitada põhjendatud poolt- või vastuväiteid. Oskab teksti siduda, kasutada erinevaid asesõnu, määrsõnu, sidendeid, kirjavahemärke."},{"title":"2. ülesanne","prompt":"Tutvu uudisega. Kommenteeri seda. Teksti pikkus olgu umbes 160 sõna. Poliitikauuringute firma Praxise hariduspoliitika programmi analüüsi „Eesti kõrghariduspoliitika: julge või juhuslik?” järgi kulutavad Eesti üliõpilased võrreldes Euroopa tudengitega kõige vähem aega õppimisele ja kõige rohkem töötamisele.\n«Praegune olukord kõneleb madalatest ülikoolipoolsetest nõudmistest, mis võimaldavad üheaegselt olla nii õppija kui ka töötegija rollis,» seisab Praxise analüüsis. «Kui üliõpilastelt ei nõuta õppetöös intensiivset osalemist ning kõrghariduse diplomi võib omandada õppetöös minimaalselt osaledes, viitab see ebakvaliteetsele õppeprotsessile.»\nEestis töötab 66 protsenti tudengkonnast, samas kui Euroopas jääb see sageli alla 50 protsendi. Samas tegelevad Eesti üliõpilased õppetööga 25 tundi nädalas, kuid paljudes Euroopa riikides on see näitaja üle 33 tunni.","audio":[],"images":[],"modelAnswer":"Mina olen osaliselt nõus selle väitega. Kuigi see on õige, et madalad ülikoolipoolsed nõudmised viitavad ebakvaliteetsele õppeprotsessile, peab ikkagi arvestama sellega, et paljud üliõpilased käivad tööl selleks, et maksta oma õpingute eest. Kui õppetöö kestaks näiteks iga päeva hommikust õhtuni, siis tudengite arv oleks jõudsalt vähenenud.\nTeiselt poolt peab ülikoolis olema kõige tähtsam lõpptulemus. Kui üliõpilasel on mugavam käia päeval tööl ja õhtul õppida omaette kodus ning kui ta suudab eksamit ära teha, siis peab seda arvestama. Iga inimene peab ise otsustama, kas ta tahab ennast pühendada ainult õppimisele või osaliselt tööle ka.\nMis puutub Euroopasse, seal on nii madal töötavate tudengite protsent põhjustatud parema majandusliku olukorra ja riigi poliitikaga. Näiteks Inglismaal annab riik igale üliõpilasele laenu, mille summa on võrdne õpingute maksumusega ning seda laenu hakkab tudeng tagasi maksma ainult sel juhul, kui tema kuupalk ületab mingit kindlat summat. Kui võrrelda Eestiga, meil inimene peab maksma igal juhul.\nNii et paljudel Eesti üliõpilastel on ainuke võimalus haridust saada käia õpingute kõrval tööl.","modelAudio":[],"modelImages":[],"comment":"Oskab kommenteerida teksti, arutleda erinevate seisukohtade ja peamiste teemade üle, avaldada oma argumenteeritud arvamust, oskab oma väljendust varieerida. Oskab teksti siduda, kasutada erinevaid asesõnu, määrsõnu, sidendeid, kirjavahemärke."}]$tt$::jsonb)
