--changeset testest:task-testest-diagnostic-b2-speaking-1 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b2-speaking-1$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B2$tt$, 1, $tt$B2 diagnoostest: rääkimine (1. variant)$tt$, $tt$B2 tanı testi: konuşma (1. varyant)$tt$, $tt$B2 diagnostic: speaking (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 351, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul koostada toodud andmetest ülevaade. Saad selleks kaks minutit ettevalmistusaega. Pead esinema sõnavõtuga, millel on nii sissejuhatus, teemaarendus kui ka lõpetus.
**Teises ülesandes **tuleb sul rääkida etteantud teemal, abiks on suunavad küsimused. Saad ühe minuti ettevalmistusaega.
Sa saad rääkimistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidisvastust ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Näed kaarti, millel on tabel andmetega. Tee nende andmete põhjal kolmeminutilise ülevaade. Ülevaatel peab olema kindel ülesehitus – sissejuhatus, teema arendus ja kokkuvõte.\nEttevalmistamiseks on aega 2 minutit. Ettevalmistusajal võid teha kirjalikke märkmeid.\nAnalüüsi, millele kulutavad eri leibkonnad oma sissetulekuid. Seejärel võrdle skeemi oma kulutustega.\nKulutused leibkonna tüübi järgi 2007","audio":[],"images":[{"src":"testest/mm_458/b2_raakimine_1v_ulesanne1.jpg"}],"modelAnswer":null,"modelAudio":["testest/mm_734/b2_raakimine1_1.mp3"],"modelImages":[],"comment":"Ülevaates järgitakse nõuetekohast ülesehitust. Rääkija väljendub võrdlemisi ladusalt ja arusaadavalt. Oskab arutleda ja võrrelda, välja tuua olulisema. Kõneleja oskab täpsustada oma seisukohti ja avaldada oma arvamust. Esineb üksikuid sõnavara- ja grammatikavigu, mis ei sega arusaamist."},{"title":"2. ülesanne","prompt":"Näed kaarti, millel on teema ja abistavad küsimused. Sinu ülesanne on sel teemal rääkida. Ettevalmistamiseks on aega üks minut. **Juhtivale tööle kandideerimine** Soovid kandideerida juhtivale tööle.\nKuidas saaksid ennast kõige paremini tutvustada?\nMissugused on sinu tugevad küljed?\nMiks peaks firma just sind valima?\nKuidas saaksid organisatsiooni tööd efektiivsemaks muuta?","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_736/b2_raakimine2_1.mp3"],"modelImages":[],"comment":"Ettekandes järgitakse nõuetekohast ülesehitust. Rääkija oskab esitada põhjendusi ja oma vaatenurka. Oskab välja tuua olulisemad seisukohad. Kõneleja oskab anda soovitusi, teha ettepanekuid ja selgitada oma arvamust. Esineb üksikuid sõnavara- ja grammatikavigu, mis ei sega arusaamist."}]$tt$::jsonb)
