INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b2-speaking-2$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B2$tt$, 2, $tt$B2 diagnoostest: rääkimine (2. variant)$tt$, $tt$B2 tanı testi: konuşma (2. varyant)$tt$, $tt$B2 diagnostic: speaking (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 352, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul teha lähteandmetele tuginedes ülevaade. Saad kaks minutit ettevalmistusaega. Esinema pead sõnavõtuga, millel on nii sissejuhatus, teemaarendus kui ka kokkuvõte.
**Teises ülesandes **tuleb rääkida etteantud teemal, abiks on suunavad küsimused. Saad ühe minuti ettevalmistusaega.
Sa saad ise rääkimistesti ülesandeid täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidist (helifaili) ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Näed kaarti, millel on tabel andmetega. Tee nende andmete põhjal kolmeminutilise ülevaade. Ülevaatel peab olema kindel ülesehitus – sissejuhatus, teema arendus ja kokkuvõte.\nEttevalmistamiseks on aega 2 minutit. Ettevalmistusajal võid teha kirjalikke märkmeid.\nAnalüüsi, millele kulutaksid töötajad paindliku tööaja korral rohkem aega. Võrdle vastuseid oma harjumustega ja põhjenda. Töötajate ajakulutus puhkamisele ja/või oma tervise eest hoolitsemisele 70% enesetäiendamisele 68% oma huvialadele 65% perele 64% majapidamistöödele 47% sõpradele 38%","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_735/b2_raakimine1_2.mp3"],"modelImages":[],"comment":"Ülevaates järgitakse nõuetekohast ülesehitust. Rääkija väljendub võrdlemisi ladusalt ja arusaadavalt. Oskab arutleda ja võrrelda, välja tuua olulisema. Kõneleja oskab täpsustada oma seisukohti ja avaldada oma arvamust. Esineb üksikuid sõnavara- ja grammatikavigu, mis ei sega arusaamist."},{"title":"2. ülesanne","prompt":"Näed kaarti, millel on teema ja abistavad küsimused. Sinu ülesanne on sel teemal rääkida. Ettevalmistamiseks on aega üks minut. **Noorte alkoholiprobleemid** Kuidas saaks vähendada alkoholiprobleeme noorte hulgas?\nMissuguseid meetmeid saaksid ette võtta noored ise, missuguseid lapsevanemad, kool ja muud organisatsioonid?\nTee oma ettepanekud.","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_737/b2_raakimine2_2.mp3"],"modelImages":[],"comment":"Ettekandes järgitakse nõuetekohast ülesehitust. Rääkija oskab esitada põhjendusi ja oma vaatenurka. Oskab välja tuua olulisemad seisukohad. Kõneleja oskab anda soovitusi, teha ettepanekuid ja selgitada oma arvamust. Esineb üksikuid sõnavara- ja grammatikavigu, mis ei sega arusaamist."}]$tt$::jsonb)
