--changeset testest:task-testest-diagnostic-b2-speaking-3 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-b2-speaking-3$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$B2$tt$, 3, $tt$B2 diagnoostest: rääkimine (3. variant)$tt$, $tt$B2 tanı testi: konuşma (3. varyant)$tt$, $tt$B2 diagnostic: speaking (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 353, 3, $tt$Rääkimise diagnoostest koosneb **kolmest ülesandest**:
– piltide võrdlemine ja lühikese kokkuvõtte tegemine,
– diagrammi analüüsimine ja selle põhjal ettekande tegemine,
– arutlus ning oma seisukohtade esitamine ja põhjendamine.
Ülesanded on **väga hästi täidetud**, kui
– suudad piltidest anda lühikese üldistava ülevaate, pilte võrrelda ja teha järeldusi sarnasuste ja erinevuste kohta,
– teed ettekande, millel on lühike sissejuhatus, teemaarendus ja lühike kokkuvõte, ning ettekande põhiosas analüüsid diagrammi, üldistad andmeid ja rõhutad olulist,
– väljendad mõtteid ja seisukohti, esitad poolt- ja vastuargumente ning selgitad ja põhjendad seisukohti, tuues asjakohaseid näiteid,
– sinu kõne on sujuv ja loomulik, kasutad grammatiliselt õiget keelt, sõnavara on ulatuslik ja sõnakasutus üldjoontes täpne.
Iga ülesande täitmine võtab aega orienteeruvalt 2–3 minutit.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Vaata pilte ja tee kokkuvõte sellest, mida piltidel näed. Võrdle pilte ja arutle, mis on nendel ühist ning millised on erinevused. 1 2 3","audio":[],"images":[{"src":"testest/mm_466/b2_raakimine_3v_yl1_1_vaike.jpg","label":"1"},{"src":"testest/mm_467/b2_raakimine_3v_yl1_2_vaike.jpg","label":"2"},{"src":"testest/mm_468/b2_raakimine_3v_yl1_3_vaike.jpg","label":"3"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Analüüsi diagrammi ja tee selle põhjal lühiettekanne.","audio":[],"images":[{"src":"testest/mm_469/b2_raakimine_3v_yl2_vaike.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"3. ülesanne","prompt":"Arutle teemal TERVISLIK ELUVIIS. Kuidas saaks laste ja noorte seas propageerida tervislikku eluviisi?\nKuidas kõige kiiremini ja lihtsamalt tööstressist vabaneda?\nKas sinu meelest on tervisliku eluviisi kohta piisavalt infot?","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
