--changeset testest:task-testest-diagnostic-c1-writing-1 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-c1-writing-1$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$C1$tt$, 1, $tt$C1 diagnoostest: kirjutamine (1. variant)$tt$, $tt$C1 tanı testi: yazma (1. varyant)$tt$, $tt$C1 diagnostic: writing (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 441, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **on sul vaja koostada ametlik kiri etteantud punktide põhjal.
**Teises ülesandes **pead kirjutama taustainfole tuginedes 300-sõnalise lühiarvamuse etteantud teemal.
Sa saad kirjutamistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisteksti ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Kandideerid rahvusvahelisse elektroonikafirmasse El‑Project AS müügijuhi ametikohale. Lisaks oma CV‑le pead saatma ka kaaskirja. Kaaskirjas peaks olema huvitav enesetutvustus, mis annaks tõuke firmajuhile sinu CVd edasi lugeda.\nKirjuta firmale El-Project AS kaaskiri (kuni 100 sõna), milles oleks pöördumine firma poole, sinu nimi ja kontaktandmed, enesetutvustus, põhjus, miks soovid just sellesse firmasse kandideerida, lugupidamisavaldus ja allkiri. Võimaliku vastuse variandi vaatamiseks klõpsa hiirega “Näidisvastus ja kommentaar” peale.","audio":[],"images":[],"modelAnswer":"**\n** El-Project AS\nMüügijuht\nGeorgi Muhhamedžanov\nKonna 209−56, 13575 Kiviõli\n55 60980\n23. märts 2009\nKAASKIRI\nSoovin kandideerida teie poolt välja kuulutatud konkursil El-Project AS müügijuhi leidmiseks.\nUsun, et töötamine teie ettevõtte müügijuhina võimaldab mul rakendada oma varasemaid müügiteadmisi ja ‑kogemusi.\nOlen töötanud turunduses viis aastat reklaamijuhi abina, kaks aastat reklaamijuhi assistendina ja viimased kolm aastat müügidirektorina Soome ühes suurimas elektroonikafirmas Nokia. Praegusel ametikohal on minu tööülesandeks tagada oma meeskonna eduka töö kaudu planeeritud müügitulude laekumine firmale ja lahendada iseseisvalt kaupade/teenuste müüki puudutavaid küsimusi.\nOma töösaavutusena praegusel ametikohal võin märkida 2009. aasta prognoositud tulude 15% ületamist.\nMul on majandusalane kõrgharidus ning magistrikraad rahvusvahelises ärijuhtimises. Olen täiendanud end mitmel müügitööga seonduval kursusel.\nMinu palgasoov on 1150 eurot (bruto) kuus.\nOlen valmis vastama teie küsimustele teile sobival ajal.\nLugupidamisega\nGeorgi Muhhamedžanov\nLisatud CV 2 lehel.","modelAudio":[],"modelImages":[],"comment":"Teksti punktid on loogiliselt järjestatud.\nHästi on jälgitud kaaskirja vormistust.\nTeksti seotakse sujuvalt: alguses tutvustatakse ennast, oma senist töökogemust, tööalaseid saavutusi ja lõpus mainitakse iseenda töökogemuste vajalikkust firmale ja palgasoovi.\nKaaskirja alustatakse sobiva sissejuhatusega (nt soovin kandideerida ).\nAvaldus lõpeb sobiva kokkuvõttega ja lõpufraasiga (nt olen valmis vastama teie küsimustele teile sobival ajal ).\nTeksti lausestus on lihtne, aga täpne.\nVallatakse oskussõnavara (nt reklaamijuhi assistent, müügitulude laekumine, magistrikraad rahvusvahelises ärijuhtimises ).\nInterpunktsioon on hea.\nÜlesanne on hästi sooritatud."},{"title":"2. ülesanne","prompt":"Praegu elab Eestis ainult sadakond inimest, kes on ehitanud endale pensionisambad, mis lubaksid vananduspõlves nautida vähemalt keskmise palga suurust pensionit. Tavainimesele on sellise eesmärgi saavutamine peaaegu võimatu, sest see nõuaks miljonite kroonide kokkuajamist.\nKirjuta lühiarvamus (kuni 300 sõna) teemal „Mida tuleks teha, et saada elamisväärset pensioni?”.","audio":[],"images":[],"modelAnswer":"**Mida tuleks teha, et saada elamisväärset pensioni?**\nEestimaal on hetkel väga päevakajaline teema pension. Kõik tööealised inimesed mõtlevad oma tulevikust ja valmistavad ennast tasapisi vanaduseks. Selleks, et saada lõpuks head pensioni tuleb mõelda peale staaži ka teistele allikatele nagu pensionisammas ja muud.\nPole saladus, et miinimupalk ei taga meile head sissetulekut pensionieas ega ka tavaline palk ei annaks tulevasele pensionärile korralikku materiaalset tuge. Keegi ei saa olla kindel, mis võib juhtuda kümne või kahekümne aasta pärast, seega tuleb alati olla valmis raskeks ajaks. Muidugi tuleb usaldada oma kohalikku krooni kuni pole märgata devalveerimise ohtu. Juhul, kui miski on muutunud ebakindlaks tuleb oma säästud üle viia kindlamasse valuutasse. Veel aasta tagasi oli paljudele noortele tööealistele lausa kohustuslik maksta 2 % oma sissetulekust teisse pensionisammasse, et pensionil saada riigilt peale riigipensioni veel lisaraha.\nKuid hiljuti mainiti kohalikus meedias, et ka ühest miljonist ei piisa elamisväärseks pensioniks. Praeguses olukorras ei saa loota, et meie noored saavad kunagi samasugust pensioni nagu paljudes Euroopa riikides. Meil on selleks veel liiga suur arenguruum ja praegused palgad ei ole võrreldavad teiste Euroopa riikidega nagu Saksamaa, Prantsusmaa ja kas või meie lähinaaber Soome. Samamoodi ei saa rääkida sellest, et mida rohkem töötad, seda rohkem saad. Paljud näevad, et meie õpetajad, insenerid ja arstid ei saa nii head palka kui nende kolleegid sama töö eest välismaal. Meil on nii-öelda keskklass palga järgi, aga mujal on nemad kõrgklass või keskmistest jõukamad. Sellest saab järeldada, et meie spetsialistid ei saa kahjuks oma palga tõttu head pensioni. Meid võib aidata üksnes entusiasm ja eneseharimine, mis ei sõltu alati rahast. Kui inimesel on üksnes sihiks suur pension, siis praegusel ajal on tal mõttekas, kas minna välismaale või võimalusel avada oma äri, mis tooks head sissetulekut ja võimaldaks palju investeerida või panna raha hoiule panka.\nTähtsam on siiski tervis pensionieas, siis on rahal vähem väärtus ja saab hakkama ka väiksema pensioniga. Muidugi tuleb loota, et kahekümne aasta pärast oleme peaaegu samal tasemel kui teised Euroopa riigid. Paraku leppime reaalsusega, mis näitab, et oma vanavanematest suuremat pensionit me ei saa.","modelAudio":[],"modelImages":[],"comment":"Tekst algab lühikese sissejuhatusega, edasi järgneb sisukas tekstiarendus ja lõppeb loogilise tekstist järelduva kokkuvõttega.\nTekst on hästi seotud, kasutatakse nii sidendeid (nt et, kui selleks et, mida ... seda, aga ) kui ka kõrvallauseid (nt keegi ei saa olla kindel, mis võib juhtuda kümne või kahekümne aasta pärast, seega tuleb alati olla valmis raskeks ajaks ).\nSuhtumis- ja hinnangusõnavara on tasemekohane (nt hetkel on, pole saladuseks, keegi ei saa kindel olla, muidugi tuleb usaldada ).\nVormimoodustus on selge ja vormivalik on mitmekesine.\nVerbist on kasutatud olevik-minevik, isikuline-umbisikuline tegumood, jaatus-eitus, kindel-tingiv kõneviis.\nKohati on ebaeestipärast sõnastust (nt säästud üle viia kindlamasse valuutasse ) ja sõnajärge (nt panna raha hoiule panka ).\nInterpunktsioon on tavapärane, eksitakse kõrvallause konstruktsioonides (nt juhul, kui miski on muutunud ebakindlaks tuleb oma säästud üle viia kindlamasse valuutasse ).\nKõigele vaatamata on teemat arendatud ühtlases võtmes ja tekst täidab ülesande eesmärki."}]$tt$::jsonb)
ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, skill = EXCLUDED.skill, cefr_level = EXCLUDED.cefr_level, variant = EXCLUDED.variant, title = EXCLUDED.title, title_tr = EXCLUDED.title_tr, title_en = EXCLUDED.title_en, source = EXCLUDED.source, sort_order = EXCLUDED.sort_order, time_limit_minutes = EXCLUDED.time_limit_minutes, intro = EXCLUDED.intro, tasks = EXCLUDED.tasks;

--changeset testest:task-testest-diagnostic-c1-writing-2 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-c1-writing-2$tt$, $tt$diagnostic$tt$, $tt$writing$tt$, $tt$C1$tt$, 2, $tt$C1 diagnoostest: kirjutamine (2. variant)$tt$, $tt$C1 tanı testi: yazma (2. varyant)$tt$, $tt$C1 diagnostic: writing (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 442, NULL, $tt$Kirjutamise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **on sul vaja koostada etteantud punktide põhjal ametlik kiri.
**Teises ülesandes **pead kirjutama taustainfole tuginedes 300-sõnalise projektitaotluse etteantud teemal.
Sa saad kirjutamistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad lugeda näidisteksti ja kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Sinu suvekodusse saadetakse prügiveofirmalt Prügiabi AS jäätmeveo teenuse eest arve. Kuid sa ei ole kunagi selle firmaga teenuslepingut sõlminud ja soovid arvet tühistada, kuna sul pole prügiveoteenust suvitusperioodil (mai−september) vaja. Soovid, et Prügiabi AS saadaks sulle väidetavalt sinuga sõlmitud lepingu koopia.\nPalun kirjuta firmale Prügiabi AS avaldus (kuni 100 sõna), milles soovid sulle saadetud arve tühistada, selgitad, et suvitusperioodil ei vaja sa prügiveoteenust, ning soovid saada väidetavalt sinuga sõlmitud lepingu koopiat.","audio":[],"images":[],"modelAnswer":"Prügiabi AS\nKäesolevaga teatan, et mina, Veera-Jevgenia Kasari, isikukood ..........., kui suvemaja omanik ei ole kunagi teie firmaga sõlminud jäätmeveolepingut ning seega loen minule teie poolt esitatud arve alusetuks.\nSuvekodu kasutan kui suvemaja maikuust kuni septembrikuuni. Sellel perioodil käideldakse jäätmed järgmiselt:\n– orgaanilised jäätmed kompostitakse ning taaskasutatakse oma maatükil;\n– paberijäätmed kasutatakse saunaahju eelkütmiseks;\n– plast‑ ja metalljäätmed sorteeritakse ning korjatakse kilekottidesse ning toimetatakse oma autoga korteriühistu konteinerisse kokkuleppe alusel, kuna prügiveoteenuste eest makstakse korteriühistule aasta läbi.\nJuhul kui teil on olemas teenusleping, mille keegi on minu nimel sõlminud, soovin ka mina selle koopiaga tutvuda. Vähemalt oleks mul võimalus sellega pöörduda politsei poole.\nLugupidamsega\nVeera-Jevgenia Kasari\n12.09.2009","modelAudio":[],"modelImages":[],"comment":"Teksti punktid on loogiliselt järjestatud.\nOskuslikult on jälgitud avalduse vormistust.\nTeksti seotakse sujuvalt: alguses tutvustatakse ennast, seletatakse probleemi olemust ja lõpus palutakse leida olukorrale lahendus.\nAvaldust alustatakse sobiva sissejuhatusega (nt käesolevaga teatan ), esitatakse oma seisukohti (nt suvekodu kasutan maikuust kuni septembrikuuni, sellel perioodil käideldakse jäätmed järgmiselt ).\nAvaldus lõpeb sobiva kokkuvõttega ( juhul kui teil on olemas teenusleping ) ja lõpufraasiga ( lugupidamisega ).\nTeksti lausestus on lihtne, aga täpne.\nKasutatakse umbisikulist tegumoodi (nt jäätmed kompostitakse, taaskasutatakse, paberijäätmed kasutatakse jne), vallatakse oskussõnavara (nt jäätmed käideldakse, prügiveoteenus, teenusleping ).\nEi eksita kollokatsioonide (nt suvekodu kasutan kui suvemaja maikuust kuni septembrikuuni, prügiveoteenuste eest makstakse korteriühistule ) ja rektsioonide (nt ei ole kunagi teie firmaga jäätmeveolepingut sõlminud, soovin selle koopiaga tutvuda ) kasutamisel. Interpunktsioon on hea.\nEsineb üleliigset ametlikku kõnepuuki (nt loen teie poolt mulle esitatud arve alusetuks, toimetatakse kokkuleppe alusel ), mis samas ei sega mõttest arusaamist. Ülesanne on hästi sooritatud."},{"title":"2. ülesanne","prompt":"Sul on võimalik saada kakssada tuhat eurot oma ammuse äriidee elluviimiseks. Kirjuta lühiprojekt raha taotlemiseks. Lühiprojekt (kuni 300 sõna) peab sisaldama äriidee nimetust, eesmärki, idee lühikirjeldust ning tööetappide loetelu ja teostamise ajakava.","audio":[],"images":[],"modelAnswer":"**Lühiprojekt**\nHospiste võrgustik on tänapäeval väga aktuaalne teema meie kodumaal. Hetkel on Eestis ainult üks hospis Ida – Tallinna Keskhaiglas.\nIgal aastal süveneb aina rohkem palliatiivse ravi vajadus Eestis. Palliatiivne ravi tähendab hooldust ja elukvaliteedi parandamist neile, kes pole enam ravitavad. See on fakt, et meil on Euroopas suurim arv HIV positiivseid ja ka vähi haigeid tuleb pidevalt juurde. Kümne aasta pärast on Eestis juba ligikaudu 6000 AIDS-i haigeid, seega paratamatult tekib vajadus hospiste jaoks. Igal inimesel on õigus väärikale surmale.\nMinu eesmärgiks on avada alguses kaks suuremat hospist Tallinna ja Narva linna, kuna seal on kõige suuremad probleemid selles valdkonnas. Hospised on spetsiaalsete osakondadega, kus vajadusel AIDS-iga kliendid on eraldatud teistest klientidest. Kõik sõltub kliendi enda soovist ja vajadustest. Hospised on mõeldud nii tasuliste kui ka tasuta kohtadega. Sõltub kliendi raskusseisundist ja spetsiifilisest hooldusest.\nHospise jaoks kulub suurem ruum, ligikaudu tavakooli suurune. Korralikus ehitatud ruumis peab kohandama igat tuba ja vannituba puuetega inimestele. Tihtipeale on paljud kliendid kõndimisvõimetud ning vajavad ratastooli. Voodid peavad olema kas poolreguleeritavad või täiestireguleeritavad. Peab olema ruum, mis oleks mõeldud sööklana 200 inimese jaoks. Hospis iseenesest on mõeldud umbes 300 inimesele, kellest üks osa on lamavad haiged ja vajavad eraldi hooldust.\nMis puudutab personali, siis on vaja peaarsti, viis medõde, onkoloogi, endokrenoloogi, kaks tegevusterapeudi, kaks füsioterapeudi, psühholoogi, kümme hooldusõde, majapidamisjuhatajat ja remondimeest.\nTeostamise ajakava on tähtajatu, mis puudutab hospise tööd. Ehitustööde jaoks kulub ligikaudu pool aastat, kui alustada ehitustööd kevadel. Samal ajal algab ka personali otsimine ja oma teenuste reklaamimine haiglates.","modelAudio":[],"modelImages":[],"comment":"Lühiprojekt on nõutust ligi viiendiku võrra lühem.\nTekst algab lühikese sissejuhatusega, edasi järgneb sisukas tekstiarendus. Lühiprojekt lõpetatakse piisava kokkuvõttega.\nTekst on sidus, kasutatakse mitmesuguseid sidendeid (nt ja, kui, seega, nii kui ka, kas või ).\nKohati on ebaeestipärast sõnajärge (nt hospis iseenesest on mõeldud ), kuid mitte häirivalt.\nLoomulikult on kasutatud küllalti keerukaid ja sõnu ja fraase (nt hospiste võrgustik, raskusseisund, elukvaliteet, täisreguleeritavad voodid ).\nSuhtumis- ja hinnangusõnavara on tasemekohane (nt aina rohkem, süveneb, paratamatult, igal inimesel on õigus, kulub ligikaudu pool aastat ).\nVormimoodustus on selge ja vormivalik on mitmekesine.\nVerbist on kasutatud olevik, isikuline-umbisikuline tegumood, jaatus-eitus.\nMuidu ladusa keelekasutuse juures esinevad mõned kokku-lahku kirjutamise vead (nt HIV positiivsed, vähi haiged ). Eksitakse ka üksiku rektsiooni kasutuses (nt tekib vajadus hospiste jaoks ).\nKokkuvõttes võib öelda, et kirjutis pole keeleliselt laitmatu ja nõutust pisut lühem, kuid vaatamata kõigele siiski positiivselt sooritatud."}]$tt$::jsonb)
ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, skill = EXCLUDED.skill, cefr_level = EXCLUDED.cefr_level, variant = EXCLUDED.variant, title = EXCLUDED.title, title_tr = EXCLUDED.title_tr, title_en = EXCLUDED.title_en, source = EXCLUDED.source, sort_order = EXCLUDED.sort_order, time_limit_minutes = EXCLUDED.time_limit_minutes, intro = EXCLUDED.intro, tasks = EXCLUDED.tasks;

