INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-c1-speaking-1$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$C1$tt$, 1, $tt$C1 diagnoostest: rääkimine (1. variant)$tt$, $tt$C1 tanı testi: konuşma (1. varyant)$tt$, $tt$C1 diagnostic: speaking (variant 1)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 451, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul esineda etteantud teemal ettekandega, millel on olemas nii sissejuhatus, teemaarendus kui ka kokkuvõte. Sulle antakse kolm minutit ettevalmistusaega.
**Teises ülesandes **pead arutlema diskussioonikaardi põhjal etteantud teemal.
Sa saad rääkimistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidisvastust ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Saad kaardi, millel on kaks teemat. Vali nende hulgast üks ja tee sellest kaheminutiline ettekanne. Ettekandel peab olema kindel ülesehitus: sissejuhatus, teema arendus ja kokkuvõte. Ettekande ettevalmistamiseks on aega 3 minutit. Ettevalmistusajal võid teha kirjalikke märkmeid. Pärast ettekande lõppu vasta esitatud küsimustele. 1. Minu kodukoha põhiprobleemid\n2. Välismaal töötamise eelised ja puudused","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_774/c1_raakimine1_v1.mp3","testest/mm_771/1_var_2_teema_jutustamine_vastaja_1.mp3"],"modelImages":[],"comment":"Ettekandes järgitakse nõuetekohast ülesehitust.\nSissejuhatuses põhjendatakse teema valikut, asetatakse probleem üldisemasse konteksti ( meie Eesti põhiprobleemid on sotsiaalsed, see teeb meile kõigile muret ) ja rõhutatakse selle olulisust ( teema on väga tähtis ja väga aktuaalne tänapäeval ).\nTeema arenduses käsitletakse kaht põhiprobleemi: töötust ja sellega kaasnevaid probleeme ning keskkonnaseisundit.\nEttekandja avab käsitletavad probleemid kompleksselt ( üks probleem on seotud teisega ) ja seob need isikliku kogemusega ( kuna ma elan Lasnamäe linnaosas ).\nTa avaldab selgelt oma arvamust (arvan et ), ja põhjendab seda oskuslikult, kasutades selleks sobivaid väljendeid ( sellepärast et ).\nEttekanne lõpeb asjakohase kokkuvõttega ( oma kõne lõpus ma sooviksin rõhutada ).\nVastused küsimustele on sisukad ja põhjendatud.\nEttekandja keelekasutus on ladus, paindlik ja tulemuslik, sõnavara rikkalik ( teema kõlab nii, üheaegselt, väljuda kriisist, tahaksin mainida, riigi initsiatiiv, puhtamat energiaallikat, rohelus ), kõnes esineb argikeelseid väljendeid ( tohutu suur ) ja loovat keelekasutust ( seletustöö ).\nÜksikud keelevead ( sõltub mitte ainult riigilt pro riigist , peaksime hakata pro peaksime hakkama ) parandab ettekandja enamasti ise.\nAktsent ei sega kõnelejast arusaamist. **Näidisvastus**\nKuula näidisvastust ja seejärel loe kommentaari.\n**Kommentaar**\nEttekandes järgitakse nõuetekohast ülesehitust.\nSissejuhatuses asetatakse probleem üldisemasse konteksti ja rõhutatakse selle olulisust ( tänapäeval palju räägitakse sellest probleemist ). Teema arenduses avatakse välismaale mineku põhjused ning käsitletakse teemat nii positiivsest kui negatiivsest aspektist, kasutades selleks sobivaid väljendeid ( esiteks, teiselt poolt ).\nEttekandja avaldab selgelt oma arvamust ( mina tahaks öelda, ma ei soovita, pigem soovitaks ) ning põhjendab seda oskuslikult.\nEttekanne lõpeb asjakohase kokkuvõttega ( kokkuvõtteks saab öelda seda ).\nVastused küsimustele on asjakohased ja sisukad ( tuleb arvestada kultuurierinevusi, mõned saavad kultuurišoki ).\nEttekandja keelekasutus on ladus, paindlik ja tulemuslik, sõnavara rikkalik ( tunneb kvalifitseeritud tööjõu puudust, uuringufirma, esialgsed plaanid, probleemid kohanemisega, olmeprobleemid ).\nÜksikud keelevead ( vaja kaaluda need eelised ja puudused pro eeliseid ja puudusi , kõrge tööpalk pro töötasu, olema-verbi puudumine ) ja aktsent ei sega kõnelejast arusaamist.\nEsineb loovat keelekasutust ( noored on väga ambitsioonilised )."},{"title":"2. ülesanne","prompt":"Saad teemakaardi. Kaardil on diskussiooni teema ja mõned mõtted, mis aitavad teemat käsitleda. Arutleme sellel teemal. Esita oma seisukohad ja põhjenda neid.\nÜlesandega tutvumiseks on aega pool minutit. Pärast teemaga tutvumist loe see ette ning alusta vestlust. **Teadussaavutused igapäevaelus** Üheks ühiskonna arengu oluliseks teguriks peetakse teadussaavutuste rakendamist eri eluvaldkondades.\nArutle testi läbiviijaga, millised on olulisemad igapäevaelu mõjutanud teadussaavutused ning mida saaks riik teha selleks, et teadustöö tulemused leiaksid majanduses ja igapäevaelus senisest enam kasutamist.","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_481/c1_raakimine2_v1.mp3"],"modelImages":[],"comment":"Testitav räägib sujuvalt ning suhtleb ladusalt ja loomulikult, arvestab suulise suhtluse kultuurilist eripära: ta liigub kiiresti vestluse põhiteema ja tuuma juurde, dialoog on kiire ja vooruvahetused lühikesed.\nTestitav kasutab siduvaid väljendeid, mis annavad edasi arvamust ( mulle tundub, aga see on minu arvamus ), suhtumist ( on tähtis, on vajalik, mulle meeldib ), nõusolekut ( nõustun ), emotsiooni ( kahjuks ei ole, aga olen kuulnud meeldivat tagasisidet ).\nTa alustab vestlust sobiva sissejuhatusega ( mulle väga meeldib, et teadussaavutustele pööratakse nii suurt tähelepanu ) ning käsitleb teemat mitmekülgselt, tuues välja nähtuste positiivsed ja negatiivsed küljed ( on oma plussid ja oma miinused igal saavutusel ).\nTestitav oskab siduda allteemasid, esitada oma seisukohti ( see on väga raske küsimus, ma kunagi olen palju selle üle mõelnud ), seostada neid olemasolevate teadmistega ( Ahhaa-keskus ) ja põhjendada ( sest kui kaua rääkida telefoniga ) ning tuua näiteid ( igasugused relvad näiteks ).\nTa arendab oskuslikult dialoogi, haarab kõnevooru ja vahetab infot. Vestlus lõpeb sobiva kokkuvõttega ( mis suunas ta areneb, sõltub juba teadlastest ).\nTestitava keelekasutus on paindlik ja tulemuslik, keelekasutuses esineb kujundlikke ( kogu meie elu on üks massiline tedussaavutus ) ja argikeelseid väljendeid."}]$tt$::jsonb)
ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, skill = EXCLUDED.skill, cefr_level = EXCLUDED.cefr_level, variant = EXCLUDED.variant, title = EXCLUDED.title, title_tr = EXCLUDED.title_tr, title_en = EXCLUDED.title_en, source = EXCLUDED.source, sort_order = EXCLUDED.sort_order, time_limit_minutes = EXCLUDED.time_limit_minutes, intro = EXCLUDED.intro, tasks = EXCLUDED.tasks;

