INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-c1-speaking-2$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$C1$tt$, 2, $tt$C1 diagnoostest: rääkimine (2. variant)$tt$, $tt$C1 tanı testi: konuşma (2. varyant)$tt$, $tt$C1 diagnostic: speaking (variant 2)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 452, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimeses ülesandes **tuleb sul esineda etteantud teemal ettekandega, millel on olemas nii sissejuhatus, teemaarendus kui ka lõpetus. Sulle antakse kolm minutit ettevalmistusaega.
**Teises ülesandes **pead arutlema diskussioonikaardi põhjal etteantud teemal.
Sa saad rääkimistesti ülesandeid ise täita, kuid ei saa tagasisidet oma vastuste kohta. Selle asemel saad kuulata näidist (helifaili) ja lugeda kommentaari.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Saad kaardi, millel on kaks teemat. Vali nende hulgast üks ja tee sellest kaheminutiline ettekanne. Ettekandel peab olema kindel ülesehitus: sissejuhatus, teema arendus ja kokkuvõte.\nEttekande ettevalmistamiseks on aega 3 minutit. Ettevalmistusajal võid teha kirjalikke märkmeid. Pärast ettekande lõppu vasta esitatud küsimustele. 1. Elukestev õpe – kellele ja milleks?\n2. Võõrkeeleoskuse roll tänapäeva maailmas","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_483/c1_raakimine1_v2.mp3","testest/mm_484/c1_raakimine1_v2_2.mp3"],"modelImages":[],"comment":"Ettekandes järgitakse nõuetekohast ülesehitust.\nTeema sissejuhatuses põhjendab ettekandja teema valikut ning selgitab selle olulisust ( olen valinud selle teema, sellepärast et see on väga aktuaalne ja pakub huvi paljudele ).\nTeema arendus algab probleemi sõnastamisega üldisemal tasandil ( kõigepealt ma sooviksin rääkida õppe laiemast aspektist, miks inimene üldse õpib ) ning on hästi liigendatud.\nEttekandja väljendab selgelt oma arvamust ( arvan, et on väga tore, kui insener õpib maalimist; ma arvan, et mitte ) ning põhjendab neid ( sellepärast et tööjõuturul on väga kõrged nõudmised ).\nÕppimise vajalikkust käsitletakse mitmekülgselt, nii tööelu kui ka isiksuse arendamise seisukohalt.\nEttekanne lõpeb asjakohase kokkuvõttega ( oma ettekande lõpuks ma sooviksin toonitada ).\nEttekandja vastab oskuslikult esitatud küsimustele ( aga miks ka mitte ).\nEttekandja keelekasutus on ladus, paindlik ja tulemuslik, sõnavara rikkalik, kasutatakse ka argikeelsed väljendid ( sellest et püsida vormis ). **Näidisvastus**\nKuula näidisvastust ja seejärel loe kommentaari.\n**Kommentaar**\nEttekandes järgitakse nõuetekohast ülesehitust.\nSissejuhatuses määratletakse probleemi olulisus ( tänapäeva maailmas võõrkeeleoskused on eriti tähtsad ).\nSeejuures võiks vältida lause alustamist sidesõnaga et .\nTeema arendus on mitmekülgne, keeleoskuse vajalikkust käsitletakse nii suurte kui ka väikeste riikide kontekstis, samuti meeldivuse ja vajalikkuse seisukohalt.\nTeemat arendades on toetub ettekandja oma kogemusele ( saksa keele õppimine Saksamaal ), väljendab oma arvamust ( mulle tundub, ma ei usu ), suhtumist ( mulle meeldib ), kahetsust ( mida ma kahjuks ei valda ), toob näiteid ( näiteks läheb puhkusele ).\nEttekandja keelekasutus on ladus, paindlik ja tulemuslik, sõnavara rikkalik."},{"title":"2. ülesanne","prompt":"Saad teemakaardi. Kaardil on diskussiooni teema ja mõned mõtted, mis aitavad teemat käsitleda. Arutleme sellel teemal. Esita oma seisukohad ja põhjenda neid.\nÜlesandega tutvumiseks on aega pool minutit. Pärast teemaga tutvumist loe ette diskussioni tema ning alusta vestlust. **Kõigile võrdne vanemahüvitis?**\nRiigi makstava vanemahüvitise suurus sõltub otseselt lapsevanema varasemast sissetulekust ja on seetõttu peredes väga erinev. Samas on laste vajadused ühesugused.\nArutle testi läbiviijaga, millist mõju avaldab keskmise palgaga seotud vanemahüvitis peredele ja inimestevahelistele suhetele ning kas oleks põhjust vanemahüvitise suurust ühtlustada.","audio":[],"images":[],"modelAnswer":null,"modelAudio":["testest/mm_485/c1_raakimine2_v2.mp3"],"modelImages":[],"comment":"Testitav räägib sujuvalt ning suhtleb ladusalt ja loomulikult, arvestab suulise suhtluse kultuurilist eripära: ta liigub kiiresti vestluse põhiteema ja tuuma juurde, dialoog on kiire ja vooruvahetused lühikesed.\nTestitav kasutab siduvaid väljendeid, mis annavad edasi arvamust ( arvan, et ), suhtumist ( see ei ole õiglane minu meelest ), osalist ( mõnes mõttes ma olen teiega nõus ) või täielikku ( täpselt nii ) nõusolekut, teadmatust ( jah, ma ei tea, ei saa sellele küsimusele vastata ).\nTa alustab vestlust sobiva kujundliku sissejuhatusega ( teema on kütnud palju kirgi viimasel ajal ), esitab üldiselt probleemi ( palju arutletakse, kas ) ning käsitleb teemat erinevatest aspektidest, üksikisiku ja riigi seisukohalt.\nTestitav oskab tuua vestlusse uued allteemad, esitada oma seisukohti ( vanemahüvitis ikkagi peab sõltuma varasemast sissetulekust ), ja põhjendada oma arvamust statistikale viidates ning tuua näiteid ( näiteks õppelaenud, kodulaenud ).\nTa arendab oskuslikult dialoogi, haarab kõnevooru ( Aga kas te ei arva, et ) ja vahetab infot.\nVestlus lõpeb kokkuvõttega (... vanemad oleksid haritud ja tublid, siis nad kasvatavad hästi lapsi ).\nTestitava keelekasutus on paindlik ja tulemuslik, väljendiga kogemata eksides oskab ta vabandada ja ennast parandada."}]$tt$::jsonb)
