--changeset testest:task-testest-diagnostic-c1-speaking-3 runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-diagnostic-c1-speaking-3$tt$, $tt$diagnostic$tt$, $tt$speaking$tt$, $tt$C1$tt$, 3, $tt$C1 diagnoostest: rääkimine (3. variant)$tt$, $tt$C1 tanı testi: konuşma (3. varyant)$tt$, $tt$C1 diagnostic: speaking (variant 3)$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 453, NULL, $tt$Rääkimise diagnoostest koosneb kahest ülesandest.
**Esimene ülesanne **on graafiku analüüsimine ja selle põhjal ettekande esitamine. Esimene ülesanne on väga hästi täidetud, kui
– teed ettekande, mis on teemakohane, hästi jälgitav, ladus ja loogiline,
– ettekandel on kindel struktuur: sissejuhatus, teemaarendus ja lühike kokkuvõte,
– ettekande põhiosas analüüsid diagrammi ja teed andmete põhjal üldistuse,
– esitad ja põhjendad oma seisukohti, rõhutad olulist ja tood üldistavaid näiteid ning
– väljendud ladusalt ja loomulikult.
**Teine ülesanne **on arutlus kahe testitava vahel, oma seisukohtade esitamine ja põhjendamine. Teine ülesanne on väga hästi täidetud, kui
– suhtled aktiivselt ja vilunult, arendad ladusalt dialoogi ja püsid teemas,
– põhjendad oma seisukohti sisukalt ja köitvalt ning tood asjakohaseid näiteid,
– arvestad vestluspartneri kõnekäitumisega, oskad kõnevooru haarata, hoida ja loovutada ning
– su kõnekäitumine tervikuna on loomulik.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Sinu ees graafikul on uuringutulemused. Sinu ülesanne on teha nende põhjal kaheminutiline suuline ettekanne haritud auditooriumile. Esita andmetest kokkuvõtlik ülevaade, tee neist järeldusi ning avalda ka oma arvamust. Sul on kolm minutit aega oma ettekande ettevalmistamiseks. Sel ajal võid teha kirjalikke märkmeid.","audio":[],"images":[{"src":"testest/mm_487/c1_raakimine_3v_yl1_vaike.gif"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Kaardil on teema ja mõned mõtted, mis aitavad seda avada. Sinu ülesanne on koos vestluskaaslasega sel teemal arutleda. Arutlus võiks kesta umbes seitse minutit. **Elukoha vahetamine**\nInimesed võtavad vastu otsuse vahetada elukohta väga erinevatel põhjustel, kolides kas ajutiselt või püsivalt Eestis ühest kohast teise või hoopiski välismaale.\nArutlege omavahel, millised olukorrad tingivad elukoha muutmist, kas see on lihtne või keeruline valik, millised nõuded see inimese ette seab ning kuidas selliseks muutuseks valmistuda.","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
