--changeset testest:task-testest-sample-b1-writing runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-b1-writing$tt$, $tt$sample$tt$, $tt$writing$tt$, $tt$B1$tt$, NULL, $tt$B1 tasemeeksami näidistest: kirjutamine$tt$, $tt$B1 sınav örneği: yazma$tt$, $tt$B1 sample exam: writing$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 240, 30, $tt$Kirjutamise näidistest koosneb kahest ülesandest.
**Esimeses ülesandes** tuleb sul täita küsimustik. Loe ülesande juhist ja vasta kümnele küsimusele. Küsimused võivad nõuda nii ühesõnalist kui ka pikemat vastust.
**Teises ülesandes** tuleb sul kirjutada isiklik kiri etteantud teemal. Teema avamist toetavad küsimused, millele sa pead oma kirjas vastama.
Kirjutamistesti tegemiseks on aega **30 minutit**.
Kummagi ülesande juures on **näidisvastus**.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Raamatukogu korraldab küsitluse, et teada saada, kuidas lugejad teenindusega rahul on. Sina oled selle raamatukogu lugeja. Vaata küsimustikku ja vasta igale küsimusele. Näidisvastused on esitatud iga küsimuse järel.\n**Räägu raamatukogu**\nRäägu 7, Kohila","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":"Tatjana Ivanova 45 aastat Olen teie raamatukogu lugeja 8 aastat. 1 kord kuus Ta asub minu maja kõrval. Tavaliselt loen vene keeles, mõnikord eesti keeles. Eelmisel nädalal. See oli eesti keele sõnastik. Mulle meeldib lugeda luuletusi ja seiklusjutte. Nad peavad viiviseid maksta [õige: maksma] . Ma kohtun siin oma sõbrannadega."},{"title":"2. ülesanne","prompt":"Sinu ühisel tuttaval oli hiljuti juubel. Sinu eestlasest sõber ei saanud aga kahjuks tulla. Kirjuta talle, kuidas pidu möödus. Kasuta kirja kirjutamisel etteantud punkte. Kus juubelit tähistati? Mida kingiti? Mida peol tehti? Kuidas Teile pidu meeldis? Teksti pikkus olgu vähemalt 100 sõna.","audio":[],"images":[],"modelAnswer":"Tere, Jaanus!\nKahju, et sa ei saanud meie sõbra sünnipäevale tulla. Mina lootsin, et kohtume pidul [õige: peol] , et meie sõpra õnnitleda jubeli [õige: juubeli] puhul koos sinuga.\nNüüd ma tahan kirjutada, kuidas pidu möödus. Tähistati juubelit ühes kohvikus Vanalinnas. Oli väga meeldiv olukord. Mängis meloodiline muusika. Laual oli palju maitsvat, erinevaid majustusi [õige: maiustusi] . Kingiti palju kingitusi. Need olid suured ilusad kimbud, kellad, suveniirid.\nPeol oli väga lõbus. Juubeljar [õige: juubilar] oli väga rõõmus, et nii palju inimesi tuli tema juurde peole. Külalised laulsid, tantsisid, mängisid erinevaid mänge. Mina tutvusin sellel peol uute inimestega, meie vahetasime ümber telefoninumbritega [õige: vahetasime telefoninumbreid] . Nad on väga toredad, heatahtlikud ja huvitavad inimesed. Sina saad hiljem nendega tuttavaks. Pidu meeldis mulle väga.\nJärgmisel aastal tahan oma sünnipäeva pidada selles kohvikus.\nPeatse kohtumiseni\nJulia","modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
