--changeset testest:task-testest-sample-b1-speaking runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-b1-speaking$tt$, $tt$sample$tt$, $tt$speaking$tt$, $tt$B1$tt$, NULL, $tt$B1 tasemeeksami näidistest: rääkimine$tt$, $tt$B1 sınav örneği: konuşma$tt$, $tt$B1 sample exam: speaking$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 250, 15, $tt$Rääkimise näidistest koosneb kahest ülesandest ja kestab umbes 15 minutit.
Esimene ülesanne koosneb kahest osast.
Ülesande esimeses osas pead vastama ühe kindla teemaga seotud küsimustele. Eksami läbiviija esitab sulle teemalehelt 5−6 küsimust.
Ülesande teine osa on vestlus sinu ja teise testitava vahel. Eksami läbiviija loeb teemalehelt ette situatsiooni ja annab teile vestlust toetava ideekaardi, kus on mõned abistavad pildid. Vestluse käigus tuleb teil väljendada oma arvamust ja soove, kirjeldada erinevaid võimalusi ning lühidalt põhjendada oma eelistusi.
Teine ülesanne on rollimäng, kus ühel testitaval tuleb infot küsida ja teisel infot anda. Ühele testitavale antakse küsimusekaart, kus on märksõnad, mille põhjal küsimusi esitada. Teisele testitavale antakse vastusekaart, mille põhjal küsimustele vastata. Küsimusekaardi saanud testitav peab ette kujutama, et ta helistab kaardil märgitud asutusse. Vastusekaardi saanud testitav peab ette kujutama, et ta on kaardil märgitud asutuse töötaja. Ülesanne on täidetud, kui vastused on leitud vähemalt viiele küsimusele.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Antud ülesanne koosneb kahest osast.\nÜlesande esimeses osas pead vastama ühe kindla teemaga seotud küsimustele. Eksami läbiviija esitab sulle teemalehelt 5−6 küsimust.\nÜlesande teine osa on vestlus sinu ja teise testitava vahel. Eksami läbiviija loeb teemalehelt ette situatsiooni ja annab sulle vestlust toetava ideekaardi, kus on mõned abistavad pildid. Vestluse käigus tuleb sul väljendada oma arvamust ja soove, kirjeldada erinevaid võimalusi ning lühidalt põhjendada oma eelistusi. **Teemaleht (eksami läbiviijale)** **Elukutse**\n**I osa**\nVariant A\nKelleks sa lapsena saada tahtsid? Miks?\nMille järgi oma elukutse valisid? / (Mille järgi valite?)\nKas elukutse valikul peaks arvestama vanemate sooviga (või sõprade soovitustega)? Miks?\nMillised ametid sinu arvates naistele ei sobi? Miks?\nMilline elukutse pole sinu arvates populaarne?\nMis vanuses võiks inimene pensionile jääda?\nVariant B\nKus ja kui kaua sa oma ametit õppisid?\nKui vanalt võiks inimene tööle minna?\nKes võiks aidata noori elukutse valiku tegemisel?\nMillised elukutsed on sinu arvates tänapäeval kõige populaarsemad? Miks?\nKui oluline on raha elukutse valikul? Miks?\nMillisel juhul peaks ametit kindlasti vahetama?\n**II osa**\nKujutage ette, et tahate mõlemad elukutset vahetada ja soovite teineteist otsuse tegemisel aidata. Arutage omavahel, missugune amet võiks teile kummalegi sobida ja miks. **Ideekaart (testitavatele)** **Elukutse: uus amet**","audio":[],"images":[{"src":"testest/mm_877/naidis_b1_raakimine_1yl_1.jpg"},{"src":"testest/mm_878/naidis_b1_raakimine_1yl_2.jpg"},{"src":"testest/mm_879/naidis_b1_raakimine_1yl_3.jpg"},{"src":"testest/mm_880/naidis_b1_raakimine_1yl_4.jpg"},{"src":"testest/mm_882/naidis_b1_raakimine_1yl_6.jpg"},{"src":"testest/mm_881/naidis_b1_raakimine_1yl_5.jpg"}],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Antud ülesanne on rollimäng, kus ühel testitaval tuleb infot küsida ja teisel infot anda. Ühele testitavale antakse küsimusekaart, kus on märksõnad, mille põhjal küsimusi esitada. Teisele testitavale antakse vastusekaart, mille põhjal küsimustele vastata.\nKüsimusekaardi saanud testitav peab ette kujutama, et ta helistab kaardil märgitud asutusse. Vastusekaardi saanud testitav peab ette kujutama, et ta on kaardil märgitud asutuse töötaja.\nÜlesanne on täidetud, kui vastused on leitud vähemalt viiele küsimusele. **Küsimusekaart** **Vastusekaart** **Teater Estonia**\nMis toimub?\nAeg?\nKoht?\nEsinejad?\nMida müüakse?\nSoodustus?\nLisainfo?\nTeater Estonia piletikassa\n**Estonia piletiturg**\n13. septembril kell 12.00\nTurg on avatud teatrimaja pargis.\nPäeva alustame tasuta kontserdiga, kus esinevad rahvusooperi solistid, koor, orkester ja balletitrupp.\nMüügile tulevad piletid kõigile selle hooaja etendustele.\nKõik piletid 20% odavamad.\nLisaks võimalik osta meeneid, teatrikostüüme- ja plakateid.\nAvatud kohvikud.\nTäpsem info kodulehel www.opera.ee","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
