--changeset testest:task-testest-sample-b2-writing runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-b2-writing$tt$, $tt$sample$tt$, $tt$writing$tt$, $tt$B2$tt$, NULL, $tt$B2 tasemeeksami näidistest: kirjutamine$tt$, $tt$B2 sınav örneği: yazma$tt$, $tt$B2 sample exam: writing$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 340, 80, $tt$Kirjutamise näidistest koosneb kahest ülesandest.
**Esimeses ülesandes** tuleb sul koostada poolametlik kiri. Ülesandes antakse situatsioonikirjeldus, andmed (kuulutus) ning suunis, millest kirja koostamisel lähtuda.
**Teises ülesandes** tuleb sul koostada kokkuvõttev tekst koos kommentaari ja isikliku seisukohaga. Tekst peab toetuma lähteandmetele (arvamusküsitluse tulemuste diagramm). Ülesande suunises on kirjas, millest pead kirjutama.
Kirjutamistesti tegemiseks on aega **80 minutit**.
Kummagi ülesande juures on **näidisvastus**.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Kujuta ette, et sinu firma otsib uusi ruume. Sa leidsid internetist alljärgneva pakkumise. Kirjuta firma esindajana kinnisvarabüroo maaklerile meil, milles teata, miks just see pakkumine teid huvitab ja milliseid ruume firma vajab, esita pakkumise põhjal täpsustavaid küsimusi, selgita, millistel tingimustel soovite ruume üürida, ning märgi oma töökoha kontaktandmed. Teksti nõutav pikkus on umbes 140 sõna. **Kinnisvarabüroo ****Modernne Kinnisvara **\n**annab üürile kontoriruumid ****(200 m²) Tartus**\nKliimaseade, nõupidamiste ruumid, sisustatud kööginurk, tasuta parkimine\nmaakler Ülle Saar\nylle@kinnisvara.ee","audio":[],"images":[],"modelAnswer":"Adressaat: ylle@kinnisvara.ee\nLugupeetud Ülle Saar\nKirjutan Teile meie firma juhtkonna nimel, sest leidsin internetist Teie pakkumise.\nMeie firma asub Tartus ja oleme pakkumisest huvitatud sellepärast, et otsime praegu uusi ja suuremaid ruume. Soovime kontorit, kus on kliimaseade, nõupidamiste ruumid ja tasuta parkla. See on meie töötajate ja klientide jaoks väga tähtis. Meile meeldib ka see, et ruumides on sisustatud kööginurk, kus töötajad saavad vabal ajal einestada.\nTeie pakkumise kohta on mul mõned küsimused.\nKõigepealt huvitab mind, mis linnaosas, missuguses hoones ja mis korrusel need ruumid asuvad. Samuti sooviksin teada, kui suur on igakuune [õige: igakuine / ühe kuu] ruumide üür. Kui kauaks te ruumid üürile annate?\nKui suured on nõupidamiste ruumid ja mitu neid on? Kas nõupidamiste ruumidel [õige: ruumides / ruumidesse] on paigaldatud projektorid?\nMeie firma soovib maksta ruumide eest üks kord kolmes kuus [õige: korra kolme kuu tagant / kord kvartalis / kolme kuu eest korraga / kolme kuu kaupa vms] . Meile sobib, kui lepingu saab sõlmida kolmeks aastaks.\nJään Teie vastust ootama.\nLugupidamisega\nTamara Tamm\nprojektijuht\nOÜ Loodustooted","modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Tutvu 2008. a lõpus korraldatud arvamusküsitluse “Inimene ja keskkond 2008” tulemustega (vt diagrammi all). Koosta tekst, milles tee küsitluse tulemustest kokkuvõte, arutle, millised on linna lähedal maal elamise eelised ja puudused, ning kirjuta, millist elupaika ise pooldate ja miks. Teksti nõutav pikkus on umbes 180 sõna. Allikas: http://www.seit.ee/failid/305.pdf","audio":[],"images":[{"src":"testest/mm_886/b2_kirjutamine.jpg"}],"modelAnswer":"2008. aasta lõpus korraldatud arvamusküsitluses „Inimene ja keskkond 2008“ osales 1003 inimest. Inimestelt küsiti, kus neile kõige enam meeldiks elada.\nÜle poole vastanutest eelistab elada linna lähedal maal. 25 % väitis, et nendel [õige: nendele] meeldiks elada linnas ja peaaegu sama suur osa, 23 % vastanutest ütles, et kõige enam meeldiks elada maal.\nMinu arvates on need väga loogilised tulemused, sest elamine linna lähedal maal võib olla väga mugav ja sellel on mitmed eelised.\nKui elada linna lähedal maal, siis võib nautida ilusat elukeskkonda ja samal ajal käia linnas nii tihti kui vaja. Aga puuduste kohta võib öelda, et näiteks kui elada linna lähedal maal, ja kõik mu sõbrad elavad linnas, on neil natuke raske külas käia, kui on tuju. Teine puudus on see, et kui elan oma majas, see nõuab tööd, et maja pärast [õige: eest] hoolitseda.\nMinu jaoks on kõige mugavam elada linnas. Mulle meeldib, et linnas on võimalik kiiresti ühest kohast teise reisida. Linnas on palju poode ja võimalusi spordiga tegelemisele [õige: tegeleda spordiga] . Mulle meeldib kohtuda sõbrannaga, minna kinno või lihtsalt kuskil kohvi juua ja vestelda. Ma olen väga sotsiaalne tüüp, mulle meeldib inimestega suhelda ja korraldada mitmesuguseid üritusi. See kõik [õige: seda kõike] on lihtsam linnas teha.\nElamine maal võib olla huvitav, lihtne, mõnikord vaikne ja ma arvestan sellega, et tulevikus tahan elada linna lähedal maal. Milline elukoht valida, sõltub inimesest ja elustiilist.","modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
