INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-b2-speaking$tt$, $tt$sample$tt$, $tt$speaking$tt$, $tt$B2$tt$, NULL, $tt$B2 tasemeeksami näidistest: rääkimine$tt$, $tt$B2 sınav örneği: konuşma$tt$, $tt$B2 sample exam: speaking$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 350, 20, $tt$Rääkimise näidistest koosneb kolmest ülesandest ja kestab umbes **20 minutit**.
**Esimeses ülesandes** pead esitama sõnavõtu (1 minut) töövaldkonnaga seotud teemal. Sa saad teemakaardi ja sulle antakse sõnavõtu ettevalmistamiseks kaks minutit. Ettevalmistamise ajal võid teha kirjalikke märkmeid. Sõnavõttu kuulab teine testitav ja esitab pärast 1−2 asjakohast küsimust.
**Teine ülesanne** on arutelu (5−6 minutit) sinu ja teise testitava vahel. Teise ülesande jaoks on eksami läbiviijal teemakaart, millelt ta esitab teile küsimusi. Te peate omavahel antud teemal arutlema, esitama oma seisukohti ja neid põhjendama.
**Kolmas ülesanne** on arutelu ja väitlus sinu ja teise testitava vahel (5−6 minutit). Eesmärk on jõuda kokkuleppele. Läbiviija loeb situatsioonilehelt ette ülesande. Sa saad loeteluga kaardi (vt kaarti A) ja sinu vestluskaaslane saab teise kaardi (vt kaarti B). Oma kaardile tuginedes peate pakkuma ülesandes kirjeldatud olukorrale lahendusi. Te peate väitlema ning põhjendama enda pakutud ideede eeliseid. Teie ülesanne on ühiselt otsustada, milline võiks olla olukorra lahendus.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Saad teemakaardi, mille alusel pead esitama sõnavõtu. Sulle antakse sõnavõtu ettevalmistamiseks 2 minutit. Ettevalmistamise ajal võid teha kirjalikke märkmeid. Sõnavõttu kuulab teine testitav ja esitab pärast 1−2 asjakohast küsimust. **Töökoormuse suurenemine**\nKujuta ette, et Sinu töökoormus on viimasel ajal oluliselt suurenenud. Seetõttu on Sinu arvates vaja tööle võtta uus töötaja. Esine töökoosolekul ja selgita, miks on lisatööjõudu vaja.","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Antud ülesanne on arutelu (5−6 minutit) sinu ja teise testitava vahel. Selle ülesande jaoks on eksami läbiviijal teemakaart, millelt ta esitab teile küsimusi (nt Palun arutlege omavahel, kas... ). Te peate omavahel antud teemal arutlema, esitama oma seisukohti ja neid põhjendama. **Elanike turvalisus**\nKas Eesti linnades on turvaline elada? Põhjenda oma seisukohta.\nKuidas saaks liiklust turvalisemaks muuta?\nKas Eesti politsei on usaldusväärne? Põhjendage oma arvamust.\nMillised inimesed sobivad politseisse tööle ja millised mitte?\nMilline roll avaliku korra tagamisel võiks olla turvafirmadel?\nMida saaks kohalik omavalitsus teha, et elukeskkond oleks turvalisem?\nMida saaksid inimesed teha oma elukeskkonna turvalisemaks muutmisel?\nKuidas saaks ära hoida õnnetusi, mis vajavad päästeteenistuse abi?","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"3. ülesanne","prompt":"Antud ülesanne on arutelu ja väitlus sinu ja teise testitava vahel (5−6 minutit). Eesmärk on jõuda kokkuleppele.\nLäbiviija loeb situatsioonilehelt ette ülesande. Saad loeteluga kaardi (vt kaarti A) ja sinu vestluskaaslane saab teise kaardi (vt kaarti B). Oma kaardile tuginedes pead pakkuma ülesandes kirjeldatud olukorrale lahendusi. Pead väitlema ning põhjendama enda pakutud ideede eeliseid. Sinu ülesanne on koos vestluskaaslasega ühiselt otsustada, milline võiks olla olukorra lahendus. **Situatsioonileht (eksami läbiviijale)**\n**Uus tööruum** Kujutage ette, et töötate ühes ja samas asutuses. Asutus kolis teise hoonesse ja te hakkate seal töötama ühes ruumis, mille saate ise valida. Arutage omavahel ja otsustage, mille põhjal uue tööruumi valite. **Kaart A** **Kaart B** **Uus tööruum**\nruumi suurus\nruumi kujundus\naknast avanev vaade **Uus tööruum**\ntöökohtade arv ruumis\nruumi seisukord\nkorrus","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
