--changeset testest:task-testest-sample-c1-writing runOnChange:true splitStatements:false stripComments:false
INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-c1-writing$tt$, $tt$sample$tt$, $tt$writing$tt$, $tt$C1$tt$, NULL, $tt$C1 tasemeeksami näidistest: kirjutamine$tt$, $tt$C1 sınav örneği: yazma$tt$, $tt$C1 sample exam: writing$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 440, 90, $tt$Kirjutamise näidistest koosneb kahest ülesandest.
**Esimeses ülesandes** tuleb sul kirjutada kokkuvõte. Ülesandes antakse juhis ning lähteandmed, mis on esitatud tabelites. Sa pead lähteandmete põhjal koostama üldistava kokkuvõtte, milles võrdled tabelites olevaid andmeid ning teed nende põhjal järeldusi.
**Teises ülesandes** tuleb sul kirjutada selge ülesehitusega (sissejuhatus, teemaarendus, kokkuvõte), hästi liigendatud pikem tekst. Ülesandes antakse situatsioonikirjeldus ning punktid teemaarenduseks, millest pead kirjutamisel lähtuma.
Kirjutamistesti tegemiseks on aega **90 minutit**.
Kummagi ülesande juures on** näidisvastus**.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Sinu ees tabelites on Statistikaameti uuringutulemused. Sinu ülesanne on neid analüüsida ning teha töökeskkonda sobiv kirjalik kokkuvõte naiste osakaalust erinevate haridusastmete õppurite seas 1996. ja 2008. aasta andmete põhjal koos omapoolsete kommentaaridega.\nArvesta sellega, et sinu lugejad tabeleid ei näe. Sellele vaatamata ära kirjuta oma teksti liiga palju arve – üldista ja too vaid mõned arvnäited oma jutu toetuseks! Kirjutisele pane kindlasti ka pealkiri.\nTeksti nõutav pikkus on umbes 180 sõna.\n**Naisõppurid tasemehariduses** **1996** **2008** **Haridusaste** **Naisõppurid** **Naisõppurite\nosakaal (%)** **Naisõppurid** **Naisõppurite\nosakaal (%)** Üldharidus 111 700 50,2 78 000 50,5 Kutseharidus 15 200 48,2 12 100 44,3 Kõrgharidus 16 000 53,0 42 400 61,9 ... bakalaureuseõpe 14 100 53,9 31 000 74,2 ... magistriõpe 1 500 53,8 10 000 61,6 ... doktoriõpe 400 49,5 1 400 52,7 **Kokku** **142 800** **52,4** **132 500** **58,2**","audio":[],"images":[],"modelAnswer":"**Naisõppurid tasemehariduses aastail 1996 ja 2008**\nAnalüüsime naisõppurite osakaalu muutumist tasemehariduses 1996. ja 2008. aasta Statistikaameti andmete põhjal. Analüüsitavad haridusastmed on üld-, kutse- ja kõrgharidus, viimase kohta on eraldi välja toodud bakalaureuse, magistri ja doktori õppeaste.\nTabeli andmetest nähtub, et kuigi naisõppurite arv on praeguseks 1996. aastaga võrreldes umbes 10 000 võrra langenud, on naiste osakaal erinevatel haridusastmetel siiski ligi 6% võrra suurenenud.\nVõib oletada, et naisõppurite hulga vähenemine üldhariduskoolides viimase kümnendi jooksul on tingitud eelkõige negatiivsest iibest. Üldhariduskoolides õppivate naisterahvaste arv on tunduvalt vähenenud, kuid on nende osakaal protsentides on jäänud samaks, seega on vähenenud ka meessoost kooliõpilaste arv.\nErinevaid õppeastmeid kõrvutades tuleb välja, et naiste seas on langenud kutsehariduse ning tõusnud kõrghariduse prestiiž. Seda tõendavad nii langus kutseharidusasutustes õppivate naiste arvus kui kõrgkoolis käivate naiste arvu märkamisväärne [õige: märkimisväärne] tõus. 2008. aastaks on naiste osakaal kutseharidusasutuste õpilaste seas alanenud, kuid tõusnud üliõpilaste seas. Samuti on kõigis kõrghariduse õppeastmetes mitmekordistunud naiste arv ning huvitav on fakt, et nii bakalaureuse- kui magistriõppes on naiste osakaal tublisti suurenenud, samal ajal kui doktorantuuris jääb meeste ja naiste suhtarv enam-vähem samaks.\nVõime järeldada, et kõrghariduse maine on ühiskonnas tervikuna, eriti aga naiste seas viimase kümne aasta jooksul oluliselt tõusnud.","modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Käisid kultuuriministeeriumi korraldatud foorumil „Muuseum 21. sajandil“. Leiad, et teema on aktuaalne ja pakub huvi ka üldsusele. Otsustad kirjutada kohalikule ajalehele artikli, milles tutvustad foorumil arutatut ja peatud lähemalt vähemalt kahel punktil. Kas tulevikuühiskonnas vajatakse muuseume? Kuidas kutsuda lapsi ja noori muuseumidesse? Muuseum kui atraktiivne vaba aja veetmise koht Teksti nõutav pikkus on umbes 250 sõna.","audio":[],"images":[],"modelAnswer":"**Kas tulevikuühiskonnas vajatakse muuseume?**\nKäisin kultuuriministeeriumi poolt korraldatud foorumil „Muuseum 21. sajandil“ ning tahaksin välja tuua mõned huvipakkuvad küsimused foorumi arutelust.\nKas on muuseumidele koht tulevikus? Võib oletada, et tänapäeva elus tegemist on vaid majandushuvidega. Esinevad arvamused, et kultuur ei too raha sisse ning ei saa ellu jääda ilma riigitoetuseta või sponsorite abita. Kultuuri säilimine – on see müüt või reaalsus meie pragmaatilises ühiskonnas?\nTõde on selles, et ühe konkreetse ühiskonna kultuur ja kunst ühtlasi kuulub ka maailmakultuuri ja kunsti. Ühiskonna suhtumine oma ajaloo ja etnograafiale [õige: ajaloosse ja etnograafiasse], mis on ka osa maailmaajaloost, oma maalikunstile [õige: maalikunsti], mis on ka osa maailma maalikunstist, näitab ühiskonna üldarengu taset.\nPaljudele samastub sõna „muuseum“ sõnaga „ajalugu“. Kas muuseumid on 21. sajandil samasugused kui aastate eest? Tegelikult on olukord vägagi muutunud. Koos teaduse ja kunsti arenguga arenevad ka muuseumid. Uhiuued modernsed maalid üha rohkem ilmuvad meie sajandi muuseumide seintele ja uuemad avastused on juba muuseumides klaasi all.\nKust turistid ja külalised välismaalt saavad teada meie kultuurist, meie lugupidamisest kunstile [õige: kunsti vastu], meie uhkusest mineviku ja käesoleva aja üle? Muuseas ka nimelt muuseumidest!\nKool peab olema vahendajaks noore põlvkonna ja muuseumide vahel. Võib tunnistada, et siiamaani seda ülesannet kool edukalt täidab. Koolilapsed käivad muuseumides üsna tihti, seega harjuvad seal käima ka tulevikus, nähes muuseumi kui kultuuri hoidlat.\nKa meie tuleva põlvkonda [õige: tulev põlvkond] ei tohi ilma muuseumideta jääda. Muuseumis on kõik – meie minevik, olevik ja tulevik. Muuseum aitab meil tunda iga ajastu eri- ja omapära. Loodan, et meie ühiskond leiab võimalusi muuseumide säilitamiseks ja arendamiseks.","modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
