INSERT INTO exam_tasks (id, kind, skill, cefr_level, variant, title, title_tr, title_en, source, sort_order, time_limit_minutes, intro, tasks)
VALUES ($tt$testest-sample-c1-speaking$tt$, $tt$sample$tt$, $tt$speaking$tt$, $tt$C1$tt$, NULL, $tt$C1 tasemeeksami näidistest: rääkimine$tt$, $tt$C1 sınav örneği: konuşma$tt$, $tt$C1 sample exam: speaking$tt$, $tt$TESTEST (Integratsiooni Sihtasutus)$tt$, 450, 20, $tt$Rääkimise näidistest koosneb kahest ülesandest ja kestab umbes **20 minutit**.
**Esimeses ülesandes** pead esitama ettekande (2 minutit) töövaldkonnaga seotud teemal. Sa saad teemakaardi, millel on kaks ettekande teemat, nendest tuleb sul välja valida üks. Sulle antakse ettekande ettevalmistamiseks kolm minutit. Sel ajal võid teha kirjalikke märkmeid. Ettekannet kuulab teine testitav ja esitab pärast 1−2 asjakohast küsimust.
**Teine ülesanne** on arutelu (7 minutit) sinu ja teise testitava vahel. Eksamineerija annab mõlemale testitavale ühesugused kaardid, millel on arutlusteema. Te peate antud teemal omavahel arutlema, esitama oma seisukohti ja neid põhjendama.$tt$, $tt$[{"title":"1. ülesanne","prompt":"Saad teemakaardi, millel on kaks ettekande teemat, nendest tuleb sul välja valida üks. Pead esitama 2 minuti pikkuse ettekande. Sulle antakse ettekande ettevalmistamiseks 3 minutit. Sel ajal võid teha kirjalikke märkmeid. Ettekannet kuulab teine testitav ja esitab pärast 1−2 asjakohast küsimust. **Teemakaart** 1. Liiklusohutuskampaaniad ja nende efektiivsus.\n2. Eesti reisirongiliikluse arendamise võimalusi.","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null},{"title":"2. ülesanne","prompt":"Antud ülesanne on arutelu (7 minutit) sinu ja teise testitava vahel. Eksamineerija annab mõlemale testitavale ühesugused kaardid, millel on arutlusteema. Te peate antud teemal omavahel arutlema, esitama oma seisukohti ja neid põhjendama. **Teemakaart** **Elukoha vahetuse otsus**\nInimesed võtavad vastu otsuse vahetada elukohta väga erinevatel põhjustel, kolides kas ajutiselt või püsivalt Eestis ühest kohast teise või hoopiski välismaale.\nArutlege omavahel, millised olukorrad tingivad elukoha muutmist, mis see kaasa toob ning kuidas selliseks muutuseks valmistuda.","audio":[],"images":[],"modelAnswer":null,"modelAudio":[],"modelImages":[],"comment":null}]$tt$::jsonb)
